def out_lines(args):
    r=subprocess.run(["./executable"]+args, env=env, capture_output=True, text=True)
    return r.stdout.splitlines()

def out_first(args):
    lines=out_lines(args)
    return lines[0] if lines else ""

def compare_s_S(txt):
    s_lines = out_lines(["-s",txt])
    S_lines = out_lines(["-S",txt])
    if not s_lines and not S_lines:
        return False
    if not s_lines or not S_lines:
        print(f"one empty for {repr(txt)}")
        return True
    if s_lines[0]!=S_lines[0]:
        print(f"diff s vs S for {repr(txt)}: s={repr(s_lines[0])} S={repr(S_lines[0])}")
        return True
    return False

for a in ["A","B","V","W","T","e","f","i","l","_","|","/","\\","[]","{}","()","<>"]:
    for b in ["A","B","V","W","T","e","_","|","/","\\","]","[", "}","{",")","(","<",">"]:
        compare_s_S(a+b)

for txt in ["AV","AW","AT","Vo","Te","fi","L_","||","__","[]","{}","()","<>","/\\","\\/","##","$$","ATAT","WAV","Il"]:
    compare_s_S(txt)

print("done comparing standard s vs S")

def compare_flags(flag1, flag2, txt, font="standard"):
    o1 = out_first(["-f",font,flag1,txt])
    o2 = out_first(["-f",font,flag2,txt])
    if o1!=o2:
        print(f"{font} {flag1} vs {flag2} for {repr(txt)}: {repr(o1)} vs {repr(o2)}")
        return True
    return False

for txt in ["AB","AV","AW","[]","__","||"]:
    compare_flags("-S","-o",txt,"banner")
    compare_flags("-s","-k",txt,"banner")
    compare_flags("-s","-S",txt,"standard")

# test banner -m values for AB: all gave same as -k except -S and -o
for m in [0,1,2,4,8,16,32,63]:
    print(f"banner m={m} AB first line {repr(out_first(['-f','banner','-m',str(m),'AB']))}")

print("banner -S", repr(out_first(["-f","banner","-S","AB"])))
print("banner -o", repr(out_first(["-f","banner","-o","AB"])))
