def parse_font(path):
    with open(path,'rb') as f:
        raw=f.readline()
    text=raw.decode('latin-1').rstrip('\r\n')
    hb=text[5]
    rest=text[6:].strip().split()
    h=int(rest[0]); comment=int(rest[4])
    with open(path,'rb') as f:
        all_lines=f.read().decode('latin-1').splitlines()
    idx=1+comment
    cmap={}
    # base 95 + 7
    base=list(range(32,127))+[196,214,220,228,246,252,223]
    for i,code in enumerate(base):
        pos=idx+i*h
        char_lines=[]
        for j in range(h):
            line=all_lines[pos+j]
            # strip terminator
            if line.endswith('@@'):
                content=line[:-2]
            elif line.endswith('@'):
                content=line[:-1]
            else:
                content=line
            char_lines.append(content)
        cmap[code]=char_lines
    return cmap, hb, h

cmap,hb,h=parse_font('fonts/standard.flf')

def get_art(ch):
    code=ord(ch)
    if code in cmap:
        return cmap[code]
    # try lower? for simplicity, if not found, use '?'
    return cmap.get(ord('?'), ['?']*h)

def count_leading(s):
    for i,ch in enumerate(s):
        if ch!=' ':
            return i
    return len(s)

def count_trailing(s):
    for i in range(len(s)-1,-1,-1):
        if s[i]!=' ':
            return len(s)-i-1
    return len(s)

def rightmost(s):
    for i in range(len(s)-1,-1,-1):
        if s[i]!=' ':
            return i
    return -1

def leftmost(s):
    for i,ch in enumerate(s):
        if ch!=' ':
            return i
    return len(s)

def print_art(art):
    for row in art:
        print(repr(row))

