# But buffer is T itself (single char). However for general, buffer width = max len of T rows? T rows len? Let's compute len of each row (including trailing spaces)
for i in range(h):
    print(f"row {i} T trailing {count_trailing(T[i])} e leading {count_leading(e[i])} sum {count_trailing(T[i])+count_leading(e[i])}")

# Minimal sum = overlap amount that can be removed without overlapping non-spaces (for kern)
overlap = min(count_trailing(T[i])+count_leading(e[i]) for i in range(h))
print("kern overlap", overlap)

# Now try to simulate smush overlap = kern overlap +1, check if possible
# For smush, we need to see at the overlapping column after shifting by overlap+1, whether characters can smush

# Build buffer as list of strings with width = max len of T
width_T = max(len(row) for row in T)
# For simplicity, pad T rows to width_T with spaces
T_padded = [row.ljust(width_T) for row in T]

# For kern, new start = width_T - overlap
start_kern = width_T - overlap
print(f"width_T {width_T} start_kern {start_kern}")

# Build combined rows for kern: result length = width_T + len(e[0]) - overlap (max)
len_e = max(len(row) for row in e)
result_len = width_T + len_e - overlap
combined_kern=[]
for i in range(h):
