def expand_control_token(token):
    # returns list of code points
    def parse_single(s, idx):
        if idx>=len(s):
            return None, idx
        ch=s[idx]
        if ch=='\\':
            if idx+1>=len(s):
                return ord('\\'), idx+1
            nxt=s[idx+1]
            if nxt=='-':
                return ord('-'), idx+2
            if nxt=='\\':
                return ord('\\'), idx+2
            # check \0x
            if s[idx+1:idx+3].lower()=='0x':
                j=idx+3
                hexd=""
                while j<len(s) and s[j] in "0123456789ABCDEFabcdef":
                    hexd+=s[j]
                    j+=1
                    if len(hexd)>=6:
                        break
                if hexd:
                    try:
                        return int(hexd,16), j
                    except:
                        return ord('\\'), idx+1
                else:
                    return ord('\\'), idx+1
            if nxt.isdigit():
                j=idx+1
                num=""
                while j<len(s) and s[j].isdigit():
                    num+=s[j]
                    j+=1
                    if len(num)>=4:
                        break
                if num:
                    try:
                        return int(num), j
                    except:
                        return ord(nxt), idx+1
                else:
                    return ord(nxt), idx+2
            else:
                return ord(nxt), idx+2
        else:
            return ord(ch), idx+1

    # handle escaped hyphen placeholder
    placeholder="\0"
    temp=token.replace("\\-", placeholder)
    if '-' in temp:
        parts=temp.split('-')
        if len(parts)==2:
            left=parts[0].replace(placeholder, "-")
            right=parts[1].replace(placeholder, "-")
            left_cp,_ = parse_single(left,0) if left else (None,0)
            # right may have multiple chars but we parse first
            right_cp,_ = parse_single(right,0) if right else (None,0)
            if left_cp is not None and right_cp is not None:
                step=1 if right_cp>=left_cp else -1
                return list(range(left_cp, right_cp+step, step))
    # no range
    cps=[]
    i=0
    while i < len(token):
        if token[i:i+2]=="\\-":
            cps.append(ord('-'))
            i+=2
            continue
        cp, ni = parse_single(token,i)
        if cp is None:
            i+=1
            continue
        cps.append(cp)
        i=ni
    return cps

def load_control_file_simple(filepath):
    # simplified: returns dict mapping and flags
    if not os.path.isfile(filepath):
        return None, "notfound"
    try:
        with open(filepath, 'rb') as f:
            data=f.read().decode('utf-8', errors='replace')
    except:
        data=""
    lines=data.splitlines()
    translations={}
    flags={'utf8':False}
    if not lines:
        return {'translations':translations,'flags':flags,'formatA':False}, None
    first=lines[0].strip()
    if first=="flc2a":
        for line in lines[1:]:
            stripped=line.strip()
            if not stripped or stripped.startswith('#'):
                continue
            cmd=stripped[0]
            if cmd=='t':
                rest=stripped[1:].strip()
                if not rest:
                    continue
                parts=rest.split()
                if len(parts)<2:
                    continue
                from_spec=parts[0]
                to_spec=parts[1]
                from_cps=expand_control_token(from_spec)
                to_cps=expand_control_token(to_spec)
                if not from_cps or not to_cps:
                    continue
                if len(to_cps)==1:
                    for fc in from_cps:
                        translations[fc]=to_cps[0]
                else:
                    for idx,fc in enumerate(from_cps):
                        if idx < len(to_cps):
                            translations[fc]=to_cps[idx]
                        else:
                            translations[fc]=to_cps[-1]
            elif cmd=='u':
                flags['utf8']=True
            elif cmd=='h':
                flags['hz']=True
            elif cmd=='f':
                continue
            else:
                # line may be like "\0x..." without t
                parts=stripped.split()
                if len(parts)>=2:
                    try:
                        from_cps=expand_control_token(parts[0])
                        to_cps=expand_control_token(parts[1])
                        if from_cps and to_cps:
                            if len(to_cps)==1:
                                for fc in from_cps:
                                    translations[fc]=to_cps[0]
                            else:
                                for idx,fc in enumerate(from_cps):
                                    if idx < len(to_cps):
                                        translations[fc]=to_cps[idx]
                                    else:
                                        translations[fc]=to_cps[-1]
                    except:
                        pass
        return {'translations':translations,'flags':flags,'formatA':False}, None
    else:
        # try Format A
        for line in lines:
            stripped=line.strip()
            if not stripped or stripped.startswith('#'):
                continue
            m=re.match(r'0x([0-9A-Fa-f]+)\s+0x([0-9A-Fa-f]+)', stripped)
            if m:
                try:
                    src=int(m.group(1),16)
                    dst=int(m.group(2),16)
                    translations[src]=dst
                except:
                    continue
        # if we found translations, treat as format A
        return {'translations':translations,'flags':flags,'formatA':True}, None

# Rendering helpers

def trim_char(art, hardblank):
    # art list of strings
    leftmosts=[]
    rightmosts=[]
    for row in art:
        lm=None
        for idx,ch in enumerate(row):
            if ch!=' ':
                lm=idx
                break
        if lm is None:
            lm=len(row)
        leftmosts.append(lm)
        rm=-1
        for idx in range(len(row)-1,-1,-1):
            if row[idx]!=' ':
                rm=idx
                break
        rightmosts.append(rm)
    common_leading = min(leftmosts) if leftmosts else 0
    trailings=[]
    for row, rm in zip(art, rightmosts):
        if rm==-1:
            trailings.append(len(row))
        else:
            trailings.append(len(row)-1-rm)
    common_trailing = min(trailings) if trailings else 0
    trimmed=[]
    for row in art:
        end = len(row)-common_trailing if common_trailing>0 else len(row)
        start = common_leading
        if start>len(row):
            trimmed.append("")
        else:
            if start> end:
                trimmed.append("")
            else:
                trimmed.append(row[start:end])
    return trimmed

def leading_blanks(row):
    for i,ch in enumerate(row):
        if ch!=' ':
            return i
    return len(row)

def trailing_blanks(row):
    for i in range(len(row)-1,-1,-1):
        if row[i]!=' ':
            return len(row)-1-i
    return len(row)

def rightmost_index(row):
    for i in range(len(row)-1,-1,-1):
        if row[i]!=' ':
            return i
    return -1

def compute_kern_overlap(buf_rows, new_rows):
    # buf_rows: current buffer (list of strings, length height, each may have length current_width)
    # new_rows: new char trimmed art
    min_overlap=None
    for brow, nrow in zip(buf_rows, new_rows):
        tb=trailing_blanks(brow)
        lb=leading_blanks(nrow)
        total=tb+lb
        if min_overlap is None or total<min_overlap:
            min_overlap=total
    if min_overlap is None:
        min_overlap=0
    return min_overlap

