def smush_pair(c1, c2, rules, hardblank):
    # c1 from buffer, c2 from new char
    # If either is space, result is other, can smush
    if c1==' ':
        return True, c2
    if c2==' ':
        return True, c1
    # hardblank handling
    if c1==hardblank and c2==hardblank:
        if rules & SM_HARDBLANK:
            return True, hardblank
        else:
            return False, None
    # If one is hardblank, generally not smushable unless hardblank rule? But for simplicity, hardblank prevents smush unless both hardblank?
    if c1==hardblank or c2==hardblank:
        # If hardblank rule not set, then hardblank is like non-space that blocks?
        # According to spec, two hardblanks smush to hardblank if rule, otherwise they don't smush.
        # If one is hardblank and other is not, they should not smush? Or hardblank overlapping should be blocked?
        # For simplicity, if one is hardblank, don't allow smush (except both hardblank case handled)
        return False, None

    # Equal
    if c1==c2:
        if rules & SM_EQUAL:
            return True, c1
        else:
            return False, None

    # Lowline: '_' can be replaced by any of |/\[]{}()<> etc
    if rules & SM_LOWLINE:
        if c1=='_':
            # check if c2 in set
            if c2 in "|/\\[]{}()<>":
                return True, c2
        if c2=='_':
            if c1 in "|/\\[]{}()<>":
                return True, c1

    # Hierarchy
    if rules & SM_HIERARCHY:
        # Determine class
        # The set includes: |, /\, [], {}, (), <>
        # For hierarchy, there is ordering: | (1), / \ (2), [] (3), {} (4), () (5), <> (6)
        # If c1 and c2 are of different classes, higher class wins? Or maybe lower? Let's guess higher wins? Let's test with earlier: For Te, maybe hierarchy needed.
        # We'll implement: if both chars are in hierarchy set, higher class wins.
        # But need to define classes more: for '/', '\' they are same class 2, etc.
        # So if both in hierarchy, higher class wins (returns char of higher class? But which char? Among the two, choose the one whose class higher? If same class, maybe not smush? Or need same class equal rule already handles same char.

        # For our implementation, we'll treat hierarchy as: if c1 and c2 are both in hierarchy dict, and their classes differ, then allow smush and return the one with higher class? Or lower?

        # Let's search memory: In FIGlet, hierarchy smushing chooses the character with higher hierarchy (i.e., more "important").

        # We'll implement higher class wins.
        if c1 in _hierarchy and c2 in _hierarchy:
            # if classes differ, allow and return higher class char (the one with higher value)
            if _hierarchy[c1]!=_hierarchy[c2]:
                # choose higher
                if _hierarchy[c1] > _hierarchy[c2]:
                    return True, c1
                else:
                    return True, c2
            # else same class, maybe not smush unless equal (already handled) ?

    # Pair: [] , {} , () , <>
    # Rule: opposite pair smushes to |
    # e.g., '[' and ']' -> '|', '{' and '}' -> '|', '(' and ')' -> '|', '<' and '>' -> '|', maybe also >< etc?
    # Let's implement: if (c1=='[' and c2==']') or (c1==']' and c2=='[') => '|'
    # similarly for {} () <>
    if rules & SM_PAIR:
        pairs = {('[',']'), (']','['), ('{','}'), ('}','{'), ('(',')'), (')','('), ('<','>'), ('>','<')}
        if (c1,c2) in pairs:
            return True, '|'

    # Big X: / \ , /\ , \/ etc smush?
    # Rule: '/' and '\' smush to '|'? Or to 'Y'? Big X: combination of / and \?
    # For example, '/' and '\' overlapping should become '|'? Or 'X'?
    # We have observed that / and \ smush with mode 16 (bigx): e.g., "\/" smushed with mode 16? Earlier we saw "\/" smushes with mode 16.
    # Let's implement bigx as:
    # '/' and '\' -> '|'? Or?
    # Also '<' and '>' smush to 'X'?
    # For simplicity, we will implement bigx as:
    # If (c1=='/' and c2=='\\') or vice versa => '|'  (or maybe 'Y'?)
    # Similarly '<' and '>' => 'X' ?
    # Let's look for known: In figlet, big X rule: / and \ smush to |? Actually I think:
    # - /\ and \/ etc produce X? Not sure.

    # We'll implement a simple version: 
    # '/' and '\' -> '|'
    # '/' and '/'? No equal already
    # '<' and '>' -> 'X' ?

    if rules & SM_BIGX:
        if (c1=='/' and c2=='\\') or (c1=='\\' and c2=='/'):
            return True, '|'
        if (c1=='<' and c2=='>') or (c1=='>' and c2=='<'):
            return True, 'X'
        # Also maybe '/' and '<' etc? Let's also handle '<' with '>'? Already.
        # For '/', '\', maybe also produce 'Y'? Let's keep simple.

    # Hardblank already handled

    # If no rule matches, cannot smush
    return False, None

