def get_font_default_layout(font):
    # Determine font's default horizontal layout
    # If full_layout !=0, use its low byte
    full = font['full_layout']
    old = font['old_layout']
    if full != 0:
        low = full & 0xFF
        # low contains bits: 1,2,4,8,16,32,64,128
        # If low & 128 => controlled smush
        # If low & 64 => kern
        # If low ==0 => full width? Or maybe ???
        # But also if low has any smush rule bits (1-32) plus smush flag, it's smush
        if low & 128:
            # controlled smush
            return 'SMUSH', low & 63
        elif low & 64:
            return 'KERN', 0
        elif low == 0:
            # full width? Or maybe old layout fallback?
            # If full==0, fallback to old
            pass
        else:
            # If low has smush rules but no 128/64? In older fonts full may have only rules? But spec says low includes 128 for smush, 64 for kern.
            # For safety, if low has any of 1-32 set, treat as smush
            if low & 63:
                return 'SMUSH', low & 63
            else:
                return 'FULL', 0
    # fallback to old_layout
    if old == -1:
        return 'FULL', 0
    elif old == 0:
        return 'KERN', 0
    elif old >0:
        # old_layout is bitmask of rules? Old values 0..15? Actually old layout up to 15 includes rules
        return 'SMUSH', old
    else:
        return 'FULL', 0

def render_text(text, font, width, justify, print_dir, layout, smush_mode, overlap, deutsch, control_files):
    # text: string (already processed for deutsch and control files)
    # We need to handle word wrapping, justification, print direction, etc.

    # Steps:
    # - Split text into lines based on \n (and handling paragraph mode outside)
    # - For each line, we need to render FIG characters into output lines

    # Simplified: We'll implement word wrapping as in FIGlet: 
    # It breaks input into words (separated by spaces). It accumulates words into a line buffer until adding next word would exceed width, then flushes.
    # But also spaces themselves have width (space FIGchar). How to handle?

