    def try_path(p):
        if os.path.isfile(p):
            return p
        return None
    def with_exts(base):
        cands=[]
        low=base.lower()
        if low.endswith('.flf') or low.endswith('.tlf'):
            cands.append(base)
        else:
            cands.append(base+'.flf')
            cands.append(base+'.tlf')
            cands.append(base)
        return cands
    if is_path:
        for cand in with_exts(fontname):
            res=try_path(cand)
            if res:
                return res
        return None
    else:
        search_dirs=[]
        if fontdir:
            search_dirs.append(fontdir)
        search_dirs.append('.')
        env_dir=os.environ.get('FIGLET_FONTDIR')
