        uniq=[]
        seen=set()
        for d in search_dirs:
            if d not in seen:
                seen.add(d)
                uniq.append(d)
        for d in uniq:
            for cand in with_exts(os.path.join(d, fontname)):
                res=try_path(cand)
                if res:
                    return res
        return None

