            return False, None
    if c1==hardblank or c2==hardblank:
        return False, None
    if c1==c2:
        if rules & SM_EQUAL:
            return True, c1
        else:
            return False, None
    if rules & SM_LOWLINE:
        if c1=='_':
            if c2 in "|/\\[]{}()<>":
                return True, c2
        if c2=='_':
            if c1 in "|/\\[]{}()<>":
                return True, c1
    if rules & SM_HIERARCHY:
        if c1 in _hierarchy and c2 in _hierarchy:
            if _hierarchy[c1]!=_hierarchy[c2]:
                if _hierarchy[c1] > _hierarchy[c2]:
                    return True, c1
                else:
                    return True, c2
    if rules & SM_PAIR:
        pairs = {('[',']'), (']','['), ('{','}'), ('}','{'), ('(',')'), (')','('), ('<','>'), ('>','<')}
