def get_font_default_layout(font):
    full = font['full_layout']
    old = font['old_layout']
    if full != 0:
        low = full & 0xFF
        if low & 128:
            return 'SMUSH', low & 63
        elif low & 64:
            return 'KERN', 0
        elif low == 0:
            pass
        else:
            if low & 63:
                return 'SMUSH', low & 63
            else:
                return 'FULL', 0
    if old == -1:
        return 'FULL', 0
    elif old == 0:
        return 'KERN', 0
    elif old >0:
        return 'SMUSH', old
    else:
        return 'FULL', 0

