                    start = cur_w - overlap
                    for j,chn in enumerate(arow):
                        pos = start + j
                        if 0 <= pos < res_len and chn!=' ':
                            res[pos]=chn
                    new_buf.append(''.join(res))
                buf = new_buf
    return buf

