SM_HARDBLANK = 32
SM_KERN = 64
SM_SMUSH = 128

def print_usage(prog, out):
    out.write(f"Usage: {prog} [ -cklnoprstvxDELNRSWX ] [ -d fontdirectory ]\n")
    out.write(f"              [ -f fontfile ] [ -m smushmode ] [ -w outputwidth ]\n")
    out.write(f"              [ -C controlfile ] [ -I infocode ] [ message ]\n")

