            return True, '|'
        if (c1=='<' and c2=='>') or (c1=='>' and c2=='<'):
            return True, 'X'
    return False, None

def smush_char_old(c1, c2, hardblank):
    if c1==' ':
        return True, c2
    if c2==' ':
        return True, c1
    if c1==hardblank and c2==hardblank:
        return True, hardblank
    if c1==hardblank or c2==hardblank:
        return False, None
    if c1==c2:
        return True, c1
    if c1=='_':
        if c2 in "|/\\[]{}()<>":
            return True, c2
    if c2=='_':
        if c1 in "|/\\[]{}()<>":
            return True, c1
    if c1 in _hierarchy and c2 in _hierarchy:
        if _hierarchy[c1]!=_hierarchy[c2]:
            if _hierarchy[c1] > _hierarchy[c2]:
                return True, c1
            else:
                return True, c2
    pairs = {('[',']'), (']','['), ('{','}'), ('}','{'), ('(',')'), (')','('), ('<','>'), ('>','<')}
    if (c1,c2) in pairs:
        return True, '|'
    if (c1=='/' and c2=='\\') or (c1=='\\' and c2=='/'):
        return True, '|'
    if (c1=='<' and c2=='>') or (c1=='>' and c2=='<'):
        return True, 'X'
    return True, c2

def get_font_default_layout(font):
    full = font['full_layout']
    old = font['old_layout']
    if full != 0:
        low = full & 0xFF
        if low & 128:
            return 'SMUSH', low & 63
        elif low & 64:
            return 'KERN', 0
        elif low == 0:
            pass
        else:
            if low & 63:
                return 'SMUSH', low & 63
            else:
                return 'FULL', 0
    if old == -1:
        return 'FULL', 0
    elif old == 0:
        return 'KERN', 0
    elif old >0:
        return 'SMUSH', old
    else:
        return 'FULL', 0

def compute_kern_overlap(buf_rows, new_rows):
    min_overlap=None
    for brow, nrow in zip(buf_rows, new_rows):
        tb=trailing_blanks(brow)
        lb=leading_blanks(nrow)
        total=tb+lb
        if min_overlap is None or total<min_overlap:
            min_overlap=total
    if min_overlap is None:
        min_overlap=0
    return min_overlap

def render_word(word, font, layout_type, smush_rules):
    height = font['height']
    hardblank = font['hardblank']
    def get_art(cp):
        art = font['cmap'].get(cp)
