def parse_header_line(line):
    if len(line) < 6:
        return None
    magic = line[:5]
    hardblank = line[5]
    rest = line[6:].strip().split()
    def get_int(idx, default=0):
        if idx < len(rest):
            try:
                return int(rest[idx])
            except:
                return default
        return default
    height = get_int(0)
    baseline = get_int(1)
    maxlen = get_int(2)
    old_layout = get_int(3)
    comment_lines = get_int(4)
    print_dir = get_int(5)
    full_layout = get_int(6)
    codetag_count = get_int(7)
    return magic, hardblank, height, baseline, maxlen, old_layout, comment_lines, print_dir, full_layout, codetag_count

def load_font_file(filepath):
    if not os.path.isfile(filepath):
        return None, "notfound"
    try:
        with open(filepath, 'rb') as f:
            first_raw = f.readline()
        first_line = first_raw.decode('latin-1').rstrip('\r\n')
    except:
        return None, "bad"
    parsed = parse_header_line(first_line)
    if parsed is None:
        return None, "bad"
    magic, hardblank, height, baseline, maxlen, old_layout, comment_lines, print_dir, full_layout, codetag_count = parsed
    if magic not in ("flf2a","tlf2a"):
        return None, "bad"
    try:
        with open(filepath, 'rb') as f:
            all_raw = f.read().decode('latin-1', errors='replace')
    except:
        return None, "bad"
    all_lines = all_raw.splitlines()
    if len(all_lines) < 1+comment_lines:
        return None, "bad"
    idx = 1+comment_lines
    base_codes = list(range(32,127)) + [196,214,220,228,246,252,223]
    cmap = {}
    for code in base_codes:
        if idx+height > len(all_lines):
            break
        char_lines=[]
        for h in range(height):
            line = all_lines[idx+h]
            if line.endswith('@@'):
                content = line[:-2]
            elif line.endswith('@'):
                content = line[:-1]
            else:
                content = line
            char_lines.append(content)
        cmap[code]=char_lines
        idx+=height
    while idx < len(all_lines):
        line = all_lines[idx].strip()
        if not line:
            idx+=1
            continue
        tok = line.split()[0] if line.split() else ""
        try:
            if tok.lower().startswith('0x'):
                code = int(tok,16)
            else:
                code = int(tok)
        except:
            break
        idx+=1
        if idx+height > len(all_lines):
            break
        char_lines=[]
        for h in range(height):
            l = all_lines[idx+h]
            if l.endswith('@@'):
                content = l[:-2]
            elif l.endswith('@'):
                content = l[:-1]
            else:
                content = l
            char_lines.append(content)
        cmap[code]=char_lines
        idx+=height
    font_data={
        'magic': magic,
        'hardblank': hardblank,
        'height': height,
        'baseline': baseline,
        'maxlen': maxlen,
        'old_layout': old_layout,
        'comment_lines': comment_lines,
        'print_dir': print_dir,
        'full_layout': full_layout,
        'codetag_count': codetag_count,
        'cmap': cmap,
        'filepath': filepath,
    }
    return font_data, None

def find_font_file(fontname, fontdir):
    is_path = ('/' in fontname or '\\' in fontname) or os.path.isabs(fontname)
    def try_path(p):
        if os.path.isfile(p):
            return p
        return None
    def with_exts(base):
        cands=[]
        low=base.lower()
        if low.endswith('.flf') or low.endswith('.tlf'):
            cands.append(base)
        else:
            cands.append(base+'.flf')
            cands.append(base+'.tlf')
            cands.append(base)
        return cands
    if is_path:
        for cand in with_exts(fontname):
            res=try_path(cand)
            if res:
                return res
        return None
    else:
        search_dirs=[]
        if fontdir:
            search_dirs.append(fontdir)
        search_dirs.append('.')
        env_dir=os.environ.get('FIGLET_FONTDIR')
        if env_dir:
            for d in env_dir.split(os.pathsep):
                if d and d not in search_dirs:
                    search_dirs.append(d)
        uniq=[]
        seen=set()
        for d in search_dirs:
            if d not in seen:
                seen.add(d)
                uniq.append(d)
        for d in uniq:
            for cand in with_exts(os.path.join(d, fontname)):
                res=try_path(cand)
                if res:
                    return res
        return None

