            buf = new_buf
        else:
            overlap = compute_kern_overlap(buf, char_rows)
            attempt = overlap + 1
            can = True
            smushed_info = []
            for i in range(height):
                brow = buf[i] if i < len(buf) else ""
                arow = char_rows[i] if i < len(char_rows) else ""
                rb = -1
                for idx in range(len(brow)-1,-1,-1):
                    if brow[idx]!=' ':
                        rb=idx
                        break
                lb = len(arow)
                for idx,ch in enumerate(arow):
                    if ch!=' ':
                        lb=idx
                        break
                if rb==-1 or lb==len(arow):
                    smushed_info.append(None)
                    continue
                c1 = brow[rb]
                c2 = arow[lb]
                if layout_type == 'SMUSH':
                    ok, rc = smush_pair(c1,c2, smush_rules, font['hardblank'])
                else:
                    ok, rc = smush_char_old(c1,c2, font['hardblank'])
                if not ok:
                    can=False
                    break
                smushed_info.append((rb,lb,rc))
            if can:
                new_w = cur_w + (max(len(r) for r in char_rows) if char_rows else 0) - attempt
                new_buf=[]
                for i in range(height):
                    brow = buf[i] if i < len(buf) else ""
                    arow = char_rows[i] if i < len(char_rows) else ""
                    res_len = new_w
                    res = [' '] * res_len
                    for j,chb in enumerate(brow):
                        if j < res_len:
                            res[j]=chb
                    start = cur_w - attempt
                    rb = -1
                    for idx in range(len(brow)-1,-1,-1):
                        if brow[idx]!=' ':
                            rb=idx
                            break
                    lb = len(arow)
                    for idx,ch in enumerate(arow):
                        if ch!=' ':
                            lb=idx
                            break
                    info = smushed_info[i] if i < len(smushed_info) else None
                    if rb!=-1 and lb!=len(arow) and info:
                        _,_,rc = info
                        if rb < res_len:
                            res[rb]=rc
                        for j in range(lb+1, len(arow)):
                            pos = start + j
                            if 0 <= pos < res_len:
                                chn=arow[j]
                                if chn!=' ':
                                    res[pos]=chn
                    else:
                        for j,chn in enumerate(arow):
                            pos = start + j
                            if 0 <= pos < res_len and chn!=' ':
                                res[pos]=chn
                    new_buf.append(''.join(res))
                buf = new_buf
            else:
                new_w = cur_w + (max(len(r) for r in char_rows) if char_rows else 0) - overlap
                new_buf=[]
                for i in range(height):
                    brow = buf[i] if i < len(buf) else ""
                    arow = char_rows[i] if i < len(char_rows) else ""
                    res_len = new_w
                    res = [' '] * res_len
                    for j,chb in enumerate(brow):
                        if j < res_len:
                            res[j]=chb
                    start = cur_w - overlap
                    for j,chn in enumerate(arow):
                        pos = start + j
                        if 0 <= pos < res_len and chn!=' ':
                            res[pos]=chn
                    new_buf.append(''.join(res))
                buf = new_buf
    return buf

def render_logical_line(log_line, font, width, justify, text_dir, layout_type, smush_rules):
    height = font['height']
    hardblank = font['hardblank']
    if width == 1:
        out=[]
        for ch in log_line:
            if ch==' ':
                continue
            cp=ord(ch)
            art=font['cmap'].get(cp)
            if art is None:
                art=font['cmap'].get(32)
                if art is None:
                    art=[""]*height
            if layout_type!='FULL':
                art=trim_char(art, hardblank)
            disp=[row.replace(hardblank,' ') for row in art]
            out.extend(disp)
        return out
    if log_line == "":
        return ["" for _ in range(height)]
    tokens = re.findall(r'\S+|\s+', log_line)
    final_lines = []
    cur_buf = ["" for _ in range(height)]

    def flush():
        nonlocal cur_buf, final_lines
        if not cur_buf or all(b=="" for b in cur_buf):
            return
        disp = [row.replace(hardblank,' ') for row in cur_buf]
        cur_w = max(len(r) for r in disp) if disp else 0
        leading=0
        if justify=='CENTER':
            leading = (width - cur_w)//2
        elif justify=='RIGHT':
            leading = width - cur_w
        elif justify=='LEFT':
            leading=0
        else:
            if text_dir=='RIGHT':
                leading = width - cur_w
            else:
                leading=0
        if leading<0:
            leading=0
        for r in disp:
            final_lines.append(' '*leading + r)
        cur_buf = ["" for _ in range(height)]

    def render_combined(buf, word):
        # returns new buf after adding word
        height = font['height']
        hardblank = font['hardblank']
        def get_art(cp):
            art = font['cmap'].get(cp)
            if art is None:
                art = font['cmap'].get(32)
                if art is None:
                    art = [""]*height
            if layout_type == 'FULL':
                return art
            else:
                return trim_char(art, hardblank)
        tmp = [row for row in buf]
        for ch in word:
            cp=ord(ch)
            char_rows = get_art(cp)
            if not tmp or all(b=="" for b in tmp):
                tmp = [row for row in char_rows]
                continue
            cur_w = max(len(r) for r in tmp)
            if layout_type=='FULL':
                new_w = cur_w + (max(len(r) for r in char_rows) if char_rows else 0)
                new_tmp=[]
                for i in range(height):
                    brow=tmp[i] if i<len(tmp) else ""
                    arow=char_rows[i] if i<len(char_rows) else ""
                    new_tmp.append(brow.ljust(cur_w)+arow)
                tmp=new_tmp
            elif layout_type=='KERN':
                overlap=compute_kern_overlap(tmp, char_rows)
                new_w=cur_w + (max(len(r) for r in char_rows) if char_rows else 0) - overlap
                new_tmp=[]
                for i in range(height):
                    brow=tmp[i] if i<len(tmp) else ""
                    arow=char_rows[i] if i<len(char_rows) else ""
                    res=[' ']*new_w
                    for j,chb in enumerate(brow):
                        if j<new_w:
                            res[j]=chb
                    start=cur_w-overlap
                    for j,chn in enumerate(arow):
                        pos=start+j
                        if 0<=pos<new_w and chn!=' ':
                            res[pos]=chn
                    new_tmp.append(''.join(res))
                tmp=new_tmp
            elif layout_type=='OVERLAP':
                art2=char_rows
                w=max(len(r) for r in art2) if art2 else 0
                if w>1:
                    art2=[row[1:] if len(row)>0 else "" for row in art2]
                overlap=compute_kern_overlap(tmp, art2)
                new_w=cur_w + (max(len(r) for r in art2) if art2 else 0) - overlap
                new_tmp=[]
                for i in range(height):
                    brow=tmp[i] if i<len(tmp) else ""
                    arow=art2[i] if i<len(art2) else ""
                    res=[' ']*new_w
                    for j,chb in enumerate(brow):
                        if j<new_w:
                            res[j]=chb
                    start=cur_w-overlap
                    for j,chn in enumerate(arow):
                        pos=start+j
                        if 0<=pos<new_w and chn!=' ':
                            res[pos]=chn
                    new_tmp.append(''.join(res))
                tmp=new_tmp
            else:
                overlap=compute_kern_overlap(tmp, char_rows)
                attempt=overlap+1
                can=True
                smushed_info=[]
                for i in range(height):
                    brow=tmp[i] if i<len(tmp) else ""
                    arow=char_rows[i] if i<len(char_rows) else ""
                    rb=-1
                    for idx in range(len(brow)-1,-1,-1):
                        if brow[idx]!=' ':
                            rb=idx
                            break
                    lb=len(arow)
                    for idx,ch in enumerate(arow):
                        if ch!=' ':
                            lb=idx
                            break
                    if rb==-1 or lb==len(arow):
                        smushed_info.append(None)
                        continue
                    c1=brow[rb]
                    c2=arow[lb]
                    if layout_type=='SMUSH':
                        ok,rc=smush_pair(c1,c2, smush_rules, hardblank)
                    else:
                        ok,rc=smush_char_old(c1,c2, hardblank)
                    if not ok:
                        can=False
                        break
                    smushed_info.append((rb,lb,rc))
                if can:
                    new_w=cur_w + (max(len(r) for r in char_rows) if char_rows else 0) - attempt
                    new_tmp=[]
                    for i in range(height):
                        brow=tmp[i] if i<len(tmp) else ""
                        arow=char_rows[i] if i<len(char_rows) else ""
                        res=[' ']*new_w
                        for j,chb in enumerate(brow):
                            if j<new_w:
                                res[j]=chb
                        start=cur_w-attempt
                        rb=-1
                        for idx in range(len(brow)-1,-1,-1):
                            if brow[idx]!=' ':
                                rb=idx
                                break
                        lb=len(arow)
                        for idx,ch in enumerate(arow):
                            if ch!=' ':
                                lb=idx
                                break
                        info=smushed_info[i] if i < len(smushed_info) else None
                        if rb!=-1 and lb!=len(arow) and info:
                            _,_,rc=info
                            if rb<new_w:
                                res[rb]=rc
                            for j in range(lb+1,len(arow)):
                                pos=start+j
                                if 0<=pos<new_w:
                                    chn=arow[j]
                                    if chn!=' ':
                                        res[pos]=chn
                        else:
                            for j,chn in enumerate(arow):
                                pos=start+j
                                if 0<=pos<new_w and chn!=' ':
                                    res[pos]=chn
                        new_tmp.append(''.join(res))
                    tmp=new_tmp
                else:
                    new_w=cur_w + (max(len(r) for r in char_rows) if char_rows else 0) - overlap
                    new_tmp=[]
                    for i in range(height):
                        brow=tmp[i] if i<len(tmp) else ""
                        arow=char_rows[i] if i<len(char_rows) else ""
                        res=[' ']*new_w
                        for j,chb in enumerate(brow):
                            if j<new_w:
                                res[j]=chb
                        start=cur_w-overlap
                        for j,chn in enumerate(arow):
                            pos=start+j
                            if 0<=pos<new_w and chn!=' ':
                                res[pos]=chn
                        new_tmp.append(''.join(res))
                    tmp=new_tmp
        return tmp

    for token in tokens:
        if token.isspace():
            if all(b=="" for b in cur_buf):
                continue
            # try adding spaces
            for _ in range(len(token)):
                # get space art
                cp=32
                art=font['cmap'].get(cp)
                if art is None:
                    art=[""]*height
                char_rows = art if layout_type=='FULL' else trim_char(art, hardblank)
                cur_w = max(len(r) for r in cur_buf) if cur_buf else 0
                overlap = 0 if layout_type=='FULL' else compute_kern_overlap(cur_buf, char_rows)
                new_w = cur_w + (max(len(r) for r in char_rows) if char_rows else 0) - overlap
                if new_w > width:
                    flush()
                    break
                else:
                    cur_buf = render_combined(cur_buf, ' ')
        else:
            word_buf = render_word(token, font, layout_type, smush_rules)
            if all(b=="" for b in cur_buf):
                cur_buf = word_buf
                continue
            tentative = render_combined(cur_buf, token)
            tent_w = max(len(r) for r in tentative) if tentative else 0
            if tent_w > width:
                flush()
                cur_buf = word_buf
            else:
                cur_buf = tentative

    if not all(b=="" for b in cur_buf):
        disp = [row.replace(hardblank,' ') for row in cur_buf]
        cur_w = max(len(r) for r in disp) if disp else 0
        leading=0
        if justify=='CENTER':
            leading = (width - cur_w)//2
        elif justify=='RIGHT':
            leading = width - cur_w
        elif justify=='LEFT':
            leading=0
        else:
            if text_dir=='RIGHT':
                leading = width - cur_w
            else:
                leading=0
        if leading<0:
            leading=0
        for r in disp:
            final_lines.append(' '*leading + r)
    return final_lines

