def expand_control_token(token):
    def parse_single(s, idx):
        if idx>=len(s):
            return None, idx
        ch=s[idx]
        if ch=='\\':
            if idx+1>=len(s):
                return ord('\\'), idx+1
            nxt=s[idx+1]
            if nxt=='-':
                return ord('-'), idx+2
            if nxt=='\\':
                return ord('\\'), idx+2
            if s[idx+1:idx+3].lower()=='0x':
                j=idx+3
                hexd=""
                while j<len(s) and s[j] in "0123456789ABCDEFabcdef":
                    hexd+=s[j]
                    j+=1
                    if len(hexd)>=6:
                        break
                if hexd:
                    try:
                        return int(hexd,16), j
                    except:
                        return ord('\\'), idx+1
                else:
                    return ord('\\'), idx+1
            if nxt.isdigit():
                j=idx+1
                num=""
                while j<len(s) and s[j].isdigit():
                    num+=s[j]
                    j+=1
                    if len(num)>=4:
                        break
                if num:
                    try:
                        return int(num), j
                    except:
                        return ord(nxt), idx+1
                else:
                    return ord(nxt), idx+2
            else:
                return ord(nxt), idx+2
        else:
            return ord(ch), idx+1
    placeholder="\0"
    temp=token.replace("\\-", placeholder)
    if '-' in temp:
        parts=temp.split('-')
        if len(parts)==2:
            left=parts[0].replace(placeholder, "-")
            right=parts[1].replace(placeholder, "-")
            left_cp,_ = parse_single(left,0) if left else (None,0)
            right_cp,_ = parse_single(right,0) if right else (None,0)
            if left_cp is not None and right_cp is not None:
                step=1 if right_cp>=left_cp else -1
                return list(range(left_cp, right_cp+step, step))
    cps=[]
    i=0
    while i < len(token):
        if token[i:i+2]=="\\-":
            cps.append(ord('-'))
            i+=2
            continue
        cp, ni = parse_single(token,i)
        if cp is None:
            i+=1
            continue
        cps.append(cp)
        i=ni
    return cps

def load_control_file_simple(filepath):
    if not os.path.isfile(filepath):
        return None, "notfound"
    try:
        with open(filepath, 'rb') as f:
            data=f.read().decode('utf-8', errors='replace')
    except:
        data=""
    lines=data.splitlines()
    translations={}
    flags={'utf8':False}
    if not lines:
        return {'translations':translations,'flags':flags,'formatA':False}, None
    first=lines[0].strip()
    if first=="flc2a":
        for line in lines[1:]:
            stripped=line.strip()
            if not stripped or stripped.startswith('#'):
                continue
            cmd=stripped[0]
            if cmd=='t':
                rest=stripped[1:].strip()
                if not rest:
                    continue
                parts=rest.split()
                if len(parts)<2:
                    continue
                from_spec=parts[0]
                to_spec=parts[1]
                from_cps=expand_control_token(from_spec)
                to_cps=expand_control_token(to_spec)
                if not from_cps or not to_cps:
                    continue
                if len(to_cps)==1:
                    for fc in from_cps:
                        translations[fc]=to_cps[0]
                else:
                    for idx,fc in enumerate(from_cps):
                        if idx < len(to_cps):
                            translations[fc]=to_cps[idx]
                        else:
                            translations[fc]=to_cps[-1]
            elif cmd=='u':
                flags['utf8']=True
            elif cmd=='f':
                continue
            else:
                parts=stripped.split()
                if len(parts)>=2:
                    try:
                        from_cps=expand_control_token(parts[0])
                        to_cps=expand_control_token(parts[1])
                        if from_cps and to_cps:
                            if len(to_cps)==1:
                                for fc in from_cps:
                                    translations[fc]=to_cps[0]
                            else:
                                for idx,fc in enumerate(from_cps):
                                    if idx < len(to_cps):
                                        translations[fc]=to_cps[idx]
                                    else:
                                        translations[fc]=to_cps[-1]
                    except:
                        pass
        return {'translations':translations,'flags':flags,'formatA':False}, None
    else:
        for line in lines:
            stripped=line.strip()
            if not stripped or stripped.startswith('#'):
                continue
            m=re.match(r'0x([0-9A-Fa-f]+)\s+0x([0-9A-Fa-f]+)', stripped)
            if m:
                try:
                    src=int(m.group(1),16)
                    dst=int(m.group(2),16)
                    translations[src]=dst
                except:
                    continue
        return {'translations':translations,'flags':flags,'formatA':True}, None

def trim_char(art, hardblank):
    leftmosts=[]
    rightmosts=[]
    for row in art:
        lm=None
        for idx,ch in enumerate(row):
            if ch!=' ':
                lm=idx
                break
        if lm is None:
            lm=len(row)
        leftmosts.append(lm)
        rm=-1
        for idx in range(len(row)-1,-1,-1):
            if row[idx]!=' ':
                rm=idx
                break
        rightmosts.append(rm)
    common_leading = min(leftmosts) if leftmosts else 0
    trailings=[]
    for row, rm in zip(art, rightmosts):
        if rm==-1:
            trailings.append(len(row))
        else:
            trailings.append(len(row)-1-rm)
    common_trailing = min(trailings) if trailings else 0
    trimmed=[]
    for row in art:
        end = len(row)-common_trailing if common_trailing>0 else len(row)
        start = common_leading
        if start>len(row):
            trimmed.append("")
        else:
            if start> end:
                trimmed.append("")
            else:
                trimmed.append(row[start:end])
    return trimmed

def leading_blanks(row):
    for i,ch in enumerate(row):
        if ch!=' ':
            return i
    return len(row)

def trailing_blanks(row):
    for i in range(len(row)-1,-1,-1):
        if row[i]!=' ':
            return len(row)-1-i
    return len(row)

def smush_pair(c1, c2, rules, hardblank):
    if c1==' ':
        return True, c2
    if c2==' ':
        return True, c1
    if c1==hardblank and c2==hardblank:
        if rules & SM_HARDBLANK:
            return True, hardblank
        else:
            return False, None
    if c1==hardblank or c2==hardblank:
        return False, None
    if c1==c2:
        if rules & SM_EQUAL:
            return True, c1
        else:
            return False, None
    if rules & SM_LOWLINE:
        if c1=='_':
            if c2 in "|/\\[]{}()<>":
                return True, c2
        if c2=='_':
            if c1 in "|/\\[]{}()<>":
                return True, c1
    if rules & SM_HIERARCHY:
        if c1 in _hierarchy and c2 in _hierarchy:
            if _hierarchy[c1]!=_hierarchy[c2]:
                if _hierarchy[c1] > _hierarchy[c2]:
                    return True, c1
                else:
                    return True, c2
    if rules & SM_PAIR:
        pairs = {('[',']'), (']','['), ('{','}'), ('}','{'), ('(',')'), (')','('), ('<','>'), ('>','<')}
        if (c1,c2) in pairs:
            return True, '|'
    if rules & SM_BIGX:
        if (c1=='/' and c2=='\\') or (c1=='\\' and c2=='/'):
            return True, '|'
        if (c1=='<' and c2=='>') or (c1=='>' and c2=='<'):
            return True, 'X'
    return False, None

def smush_char_old(c1, c2, hardblank):
    if c1==' ':
        return True, c2
    if c2==' ':
        return True, c1
    if c1==hardblank and c2==hardblank:
        return True, hardblank
    if c1==hardblank or c2==hardblank:
        return False, None
    if c1==c2:
        return True, c1
    if c1=='_':
        if c2 in "|/\\[]{}()<>":
            return True, c2
    if c2=='_':
        if c1 in "|/\\[]{}()<>":
            return True, c1
    if c1 in _hierarchy and c2 in _hierarchy:
        if _hierarchy[c1]!=_hierarchy[c2]:
            if _hierarchy[c1] > _hierarchy[c2]:
                return True, c1
            else:
                return True, c2
    pairs = {('[',']'), (']','['), ('{','}'), ('}','{'), ('(',')'), (')','('), ('<','>'), ('>','<')}
    if (c1,c2) in pairs:
        return True, '|'
    if (c1=='/' and c2=='\\') or (c1=='\\' and c2=='/'):
        return True, '|'
    if (c1=='<' and c2=='>') or (c1=='>' and c2=='<'):
        return True, 'X'
    return True, c2

def get_font_default_layout(font):
    full = font['full_layout']
    old = font['old_layout']
    if full != 0:
        low = full & 0xFF
        if low & 128:
            return 'SMUSH', low & 63
        elif low & 64:
            return 'KERN', 0
        elif low == 0:
            pass
        else:
            if low & 63:
                return 'SMUSH', low & 63
            else:
                return 'FULL', 0
    if old == -1:
        return 'FULL', 0
    elif old == 0:
        return 'KERN', 0
    elif old >0:
        return 'SMUSH', old
    else:
        return 'FULL', 0

def compute_kern_overlap(buf_rows, new_rows):
    min_overlap=None
    for brow, nrow in zip(buf_rows, new_rows):
        tb=trailing_blanks(brow)
        lb=leading_blanks(nrow)
        total=tb+lb
        if min_overlap is None or total<min_overlap:
            min_overlap=total
    if min_overlap is None:
        min_overlap=0
    return min_overlap

def render_word(word, font, layout_type, smush_rules):
    height = font['height']
    def get_art(cp):
        art = font['cmap'].get(cp)
        if art is None:
            art = font['cmap'].get(32)
            if art is None:
                art = [""]*height
        if layout_type == 'FULL':
            return art
        else:
            return trim_char(art, font['hardblank'])
    buf = ["" for _ in range(height)]
    first=True
    for ch in word:
        cp = ord(ch)
        char_rows = get_art(cp)
        if first:
            buf = [row for row in char_rows]
            first=False
            continue
        cur_w = max(len(r) for r in buf)
        if layout_type == 'FULL':
            new_w = cur_w + (max(len(r) for r in char_rows) if char_rows else 0)
            new_buf=[]
            for i in range(height):
                brow = buf[i] if i < len(buf) else ""
                arow = char_rows[i] if i < len(char_rows) else ""
                brow_p = brow.ljust(cur_w)
                new_buf.append(brow_p + arow)
            buf = new_buf
        elif layout_type == 'KERN':
            overlap = compute_kern_overlap(buf, char_rows)
            new_w = cur_w + (max(len(r) for r in char_rows) if char_rows else 0) - overlap
            new_buf=[]
            for i in range(height):
                brow = buf[i] if i < len(buf) else ""
                arow = char_rows[i] if i < len(char_rows) else ""
                res_len = new_w
                res = [' '] * res_len
                for j,chb in enumerate(brow):
                    if j < res_len:
                        res[j]=chb
                start = cur_w - overlap
                for j,chn in enumerate(arow):
                    pos = start + j
                    if 0 <= pos < res_len and chn!=' ':
                        res[pos]=chn
                new_buf.append(''.join(res))
            buf = new_buf
        elif layout_type == 'OVERLAP':
            art2 = char_rows
            w = max(len(r) for r in art2) if art2 else 0
            if w > 1:
                art2 = [row[1:] if len(row)>0 else "" for row in art2]
            overlap = compute_kern_overlap(buf, art2)
            new_w = cur_w + (max(len(r) for r in art2) if art2 else 0) - overlap
            new_buf=[]
            for i in range(height):
                brow = buf[i] if i < len(buf) else ""
                arow = art2[i] if i < len(art2) else ""
                res_len = new_w
                res = [' '] * res_len
                for j,chb in enumerate(brow):
                    if j < res_len:
                        res[j]=chb
                start = cur_w - overlap
                for j,chn in enumerate(arow):
                    pos = start + j
                    if 0 <= pos < res_len and chn!=' ':
                        res[pos]=chn
                new_buf.append(''.join(res))
            buf = new_buf
        else:
            overlap = compute_kern_overlap(buf, char_rows)
            attempt = overlap + 1
            can = True
            smushed_info = []
            for i in range(height):
                brow = buf[i] if i < len(buf) else ""
                arow = char_rows[i] if i < len(char_rows) else ""
                rb = -1
                for idx in range(len(brow)-1,-1,-1):
                    if brow[idx]!=' ':
                        rb=idx
                        break
                lb = len(arow)
                for idx,ch in enumerate(arow):
                    if ch!=' ':
                        lb=idx
                        break
                if rb==-1 or lb==len(arow):
                    smushed_info.append(None)
                    continue
                c1 = brow[rb]
                c2 = arow[lb]
                if layout_type == 'SMUSH':
                    ok, rc = smush_pair(c1,c2, smush_rules, font['hardblank'])
                else:
                    ok, rc = smush_char_old(c1,c2, font['hardblank'])
                if not ok:
                    can=False
                    break
                smushed_info.append((rb,lb,rc))
            if can:
                new_w = cur_w + (max(len(r) for r in char_rows) if char_rows else 0) - attempt
                new_buf=[]
                for i in range(height):
                    brow = buf[i] if i < len(buf) else ""
                    arow = char_rows[i] if i < len(char_rows) else ""
                    res_len = new_w
                    res = [' '] * res_len
                    for j,chb in enumerate(brow):
                        if j < res_len:
                            res[j]=chb
                    start = cur_w - attempt
                    rb = -1
                    for idx in range(len(brow)-1,-1,-1):
                        if brow[idx]!=' ':
                            rb=idx
                            break
                    lb = len(arow)
                    for idx,ch in enumerate(arow):
                        if ch!=' ':
                            lb=idx
                            break
                    info = smushed_info[i] if i < len(smushed_info) else None
                    if rb!=-1 and lb!=len(arow) and info:
                        _,_,rc = info
                        if rb < res_len:
                            res[rb]=rc
                        for j in range(lb+1, len(arow)):
                            pos = start + j
                            if 0 <= pos < res_len:
                                chn=arow[j]
                                if chn!=' ':
                                    res[pos]=chn
                    else:
                        for j,chn in enumerate(arow):
                            pos = start + j
                            if 0 <= pos < res_len and chn!=' ':
                                res[pos]=chn
                    new_buf.append(''.join(res))
                buf = new_buf
            else:
                new_w = cur_w + (max(len(r) for r in char_rows) if char_rows else 0) - overlap
                new_buf=[]
                for i in range(height):
                    brow = buf[i] if i < len(buf) else ""
                    arow = char_rows[i] if i < len(char_rows) else ""
                    res_len = new_w
                    res = [' '] * res_len
                    for j,chb in enumerate(brow):
                        if j < res_len:
                            res[j]=chb
                    start = cur_w - overlap
                    for j,chn in enumerate(arow):
                        pos = start + j
                        if 0 <= pos < res_len and chn!=' ':
                            res[pos]=chn
                    new_buf.append(''.join(res))
                buf = new_buf
    return buf

def render_logical_line(log_line, font, width, justify, text_dir, layout_type, smush_rules):
    height = font['height']
    hardblank = font['hardblank']
    if width == 1:
        out=[]
        for ch in log_line:
            if ch==' ':
                continue
            cp=ord(ch)
            art=font['cmap'].get(cp)
            if art is None:
                art=font['cmap'].get(32)
                if art is None:
                    art=[""]*height
            if layout_type!='FULL':
                art=trim_char(art, hardblank)
            disp=[row.replace(hardblank,' ') for row in art]
            out.extend(disp)
        return out
    if log_line == "":
        return ["" for _ in range(height)]
    tokens = re.findall(r'\S+|\s+', log_line)
    final_lines = []
    cur_buf = ["" for _ in range(height)]

    def flush():
        nonlocal cur_buf, final_lines
        if not cur_buf or all(b=="" for b in cur_buf):
            return
        disp = [row.replace(hardblank,' ') for row in cur_buf]
        cur_w = max(len(r) for r in disp) if disp else 0
        leading=0
        if justify=='CENTER':
            leading = (width - cur_w)//2
        elif justify=='RIGHT':
            leading = width - cur_w
        elif justify=='LEFT':
            leading=0
        else:
            if text_dir=='RIGHT':
                leading = width - cur_w
            else:
                leading=0
        if leading<0:
            leading=0
        for r in disp:
            final_lines.append(' '*leading + r)
        cur_buf = ["" for _ in range(height)]

    def render_combined(buf, word):
        # returns new buf after adding word
        height = font['height']
        hardblank = font['hardblank']
        def get_art(cp):
            art = font['cmap'].get(cp)
            if art is None:
                art = font['cmap'].get(32)
                if art is None:
                    art = [""]*height
            if layout_type == 'FULL':
                return art
            else:
                return trim_char(art, hardblank)
        tmp = [row for row in buf]
        for ch in word:
            cp=ord(ch)
            char_rows = get_art(cp)
            if not tmp or all(b=="" for b in tmp):
                tmp = [row for row in char_rows]
                continue
            cur_w = max(len(r) for r in tmp)
            if layout_type=='FULL':
                new_w = cur_w + (max(len(r) for r in char_rows) if char_rows else 0)
                new_tmp=[]
                for i in range(height):
                    brow=tmp[i] if i<len(tmp) else ""
                    arow=char_rows[i] if i<len(char_rows) else ""
                    new_tmp.append(brow.ljust(cur_w)+arow)
                tmp=new_tmp
            elif layout_type=='KERN':
                overlap=compute_kern_overlap(tmp, char_rows)
                new_w=cur_w + (max(len(r) for r in char_rows) if char_rows else 0) - overlap
                new_tmp=[]
                for i in range(height):
                    brow=tmp[i] if i<len(tmp) else ""
                    arow=char_rows[i] if i<len(char_rows) else ""
                    res=[' ']*new_w
                    for j,chb in enumerate(brow):
                        if j<new_w:
                            res[j]=chb
                    start=cur_w-overlap
                    for j,chn in enumerate(arow):
                        pos=start+j
                        if 0<=pos<new_w and chn!=' ':
                            res[pos]=chn
                    new_tmp.append(''.join(res))
                tmp=new_tmp
            elif layout_type=='OVERLAP':
                art2=char_rows
                w=max(len(r) for r in art2) if art2 else 0
                if w>1:
                    art2=[row[1:] if len(row)>0 else "" for row in art2]
                overlap=compute_kern_overlap(tmp, art2)
                new_w=cur_w + (max(len(r) for r in art2) if art2 else 0) - overlap
                new_tmp=[]
                for i in range(height):
                    brow=tmp[i] if i<len(tmp) else ""
                    arow=art2[i] if i<len(art2) else ""
                    res=[' ']*new_w
                    for j,chb in enumerate(brow):
                        if j<new_w:
                            res[j]=chb
                    start=cur_w-overlap
                    for j,chn in enumerate(arow):
                        pos=start+j
                        if 0<=pos<new_w and chn!=' ':
                            res[pos]=chn
                    new_tmp.append(''.join(res))
                tmp=new_tmp
            else:
                overlap=compute_kern_overlap(tmp, char_rows)
                attempt=overlap+1
                can=True
                smushed_info=[]
                for i in range(height):
                    brow=tmp[i] if i<len(tmp) else ""
                    arow=char_rows[i] if i<len(char_rows) else ""
                    rb=-1
                    for idx in range(len(brow)-1,-1,-1):
                        if brow[idx]!=' ':
                            rb=idx
                            break
                    lb=len(arow)
                    for idx,ch in enumerate(arow):
                        if ch!=' ':
                            lb=idx
                            break
                    if rb==-1 or lb==len(arow):
                        smushed_info.append(None)
                        continue
                    c1=brow[rb]
                    c2=arow[lb]
                    if layout_type=='SMUSH':
                        ok,rc=smush_pair(c1,c2, smush_rules, hardblank)
                    else:
                        ok,rc=smush_char_old(c1,c2, hardblank)
                    if not ok:
                        can=False
                        break
                    smushed_info.append((rb,lb,rc))
                if can:
                    new_w=cur_w + (max(len(r) for r in char_rows) if char_rows else 0) - attempt
                    new_tmp=[]
                    for i in range(height):
                        brow=tmp[i] if i<len(tmp) else ""
                        arow=char_rows[i] if i<len(char_rows) else ""
                        res=[' ']*new_w
                        for j,chb in enumerate(brow):
                            if j<new_w:
                                res[j]=chb
                        start=cur_w-attempt
                        rb=-1
                        for idx in range(len(brow)-1,-1,-1):
                            if brow[idx]!=' ':
                                rb=idx
                                break
                        lb=len(arow)
                        for idx,ch in enumerate(arow):
                            if ch!=' ':
                                lb=idx
                                break
                        info=smushed_info[i] if i < len(smushed_info) else None
                        if rb!=-1 and lb!=len(arow) and info:
                            _,_,rc=info
                            if rb<new_w:
                                res[rb]=rc
                            for j in range(lb+1,len(arow)):
                                pos=start+j
                                if 0<=pos<new_w:
                                    chn=arow[j]
                                    if chn!=' ':
                                        res[pos]=chn
                        else:
                            for j,chn in enumerate(arow):
                                pos=start+j
                                if 0<=pos<new_w and chn!=' ':
                                    res[pos]=chn
                        new_tmp.append(''.join(res))
                    tmp=new_tmp
                else:
                    new_w=cur_w + (max(len(r) for r in char_rows) if char_rows else 0) - overlap
                    new_tmp=[]
                    for i in range(height):
                        brow=tmp[i] if i<len(tmp) else ""
                        arow=char_rows[i] if i<len(char_rows) else ""
                        res=[' ']*new_w
                        for j,chb in enumerate(brow):
                            if j<new_w:
                                res[j]=chb
                        start=cur_w-overlap
                        for j,chn in enumerate(arow):
                            pos=start+j
                            if 0<=pos<new_w and chn!=' ':
                                res[pos]=chn
                        new_tmp.append(''.join(res))
                    tmp=new_tmp
        return tmp

    for token in tokens:
        if token.isspace():
            if all(b=="" for b in cur_buf):
                continue
            # try adding spaces
            for _ in range(len(token)):
                # get space art
                cp=32
                art=font['cmap'].get(cp)
                if art is None:
                    art=[""]*height
                char_rows = art if layout_type=='FULL' else trim_char(art, hardblank)
                cur_w = max(len(r) for r in cur_buf) if cur_buf else 0
                overlap = 0 if layout_type=='FULL' else compute_kern_overlap(cur_buf, char_rows)
                new_w = cur_w + (max(len(r) for r in char_rows) if char_rows else 0) - overlap
                if new_w > width:
                    flush()
                    break
                else:
                    cur_buf = render_combined(cur_buf, ' ')
        else:
            word_buf = render_word(token, font, layout_type, smush_rules)
            if all(b=="" for b in cur_buf):
                cur_buf = word_buf
                continue
            tentative = render_combined(cur_buf, token)
            tent_w = max(len(r) for r in tentative) if tentative else 0
            if tent_w > width:
                flush()
                cur_buf = word_buf
            else:
                cur_buf = tentative

    if not all(b=="" for b in cur_buf):
        disp = [row.replace(hardblank,' ') for row in cur_buf]
        cur_w = max(len(r) for r in disp) if disp else 0
        leading=0
        if justify=='CENTER':
            leading = (width - cur_w)//2
        elif justify=='RIGHT':
            leading = width - cur_w
        elif justify=='LEFT':
            leading=0
        else:
            if text_dir=='RIGHT':
                leading = width - cur_w
            else:
                leading=0
        if leading<0:
            leading=0
        for r in disp:
            final_lines.append(' '*leading + r)
    return final_lines

