                hexd=""
                while j<len(s) and s[j] in "0123456789ABCDEFabcdef":
                    hexd+=s[j]
                    j+=1
                    if len(hexd)>=6:
                        break
                if hexd:
                    try:
                        return int(hexd,16), j
                    except:
                        return ord('\\'), idx+1
                else:
                    return ord('\\'), idx+1
            if nxt.isdigit():
                j=idx+1
                num=""
                while j<len(s) and s[j].isdigit():
                    num+=s[j]
                    j+=1
                    if len(num)>=4:
                        break
                if num:
                    try:
                        return int(num), j
                    except:
                        return ord(nxt), idx+1
                else:
                    return ord(nxt), idx+2
            else:
                return ord(nxt), idx+2
        else:
            return ord(ch), idx+1
    placeholder="\0"
    temp=token.replace("\\-", placeholder)
    if '-' in temp:
        parts=temp.split('-')
        if len(parts)==2:
            left=parts[0].replace(placeholder, "-")
            right=parts[1].replace(placeholder, "-")
            left_cp,_ = parse_single(left,0) if left else (None,0)
            right_cp,_ = parse_single(right,0) if right else (None,0)
            if left_cp is not None and right_cp is not None:
                step=1 if right_cp>=left_cp else -1
                return list(range(left_cp, right_cp+step, step))
    cps=[]
    i=0
    while i < len(token):
        if token[i:i+2]=="\\-":
            cps.append(ord('-'))
            i+=2
            continue
        cp, ni = parse_single(token,i)
        if cp is None:
            i+=1
            continue
        cps.append(cp)
        i=ni
    return cps

def load_control_file_simple(filepath):
    if not os.path.isfile(filepath):
        return None, "notfound"
    try:
        with open(filepath, 'rb') as f:
            data=f.read().decode('utf-8', errors='replace')
    except:
        data=""
    lines=data.splitlines()
    translations={}
    flags={'utf8':False}
    if not lines:
        return {'translations':translations,'flags':flags,'formatA':False}, None
    first=lines[0].strip()
    if first=="flc2a":
        for line in lines[1:]:
            stripped=line.strip()
            if not stripped or stripped.startswith('#'):
                continue
            cmd=stripped[0]
            if cmd=='t':
                rest=stripped[1:].strip()
                if not rest:
                    continue
                parts=rest.split()
                if len(parts)<2:
                    continue
                from_spec=parts[0]
                to_spec=parts[1]
                from_cps=expand_control_token(from_spec)
                to_cps=expand_control_token(to_spec)
                if not from_cps or not to_cps:
                    continue
                if len(to_cps)==1:
                    for fc in from_cps:
                        translations[fc]=to_cps[0]
                else:
                    for idx,fc in enumerate(from_cps):
                        if idx < len(to_cps):
                            translations[fc]=to_cps[idx]
                        else:
                            translations[fc]=to_cps[-1]
            elif cmd=='u':
                flags['utf8']=True
            elif cmd=='f':
                continue
            else:
                parts=stripped.split()
                if len(parts)>=2:
                    try:
                        from_cps=expand_control_token(parts[0])
                        to_cps=expand_control_token(parts[1])
                        if from_cps and to_cps:
                            if len(to_cps)==1:
                                for fc in from_cps:
                                    translations[fc]=to_cps[0]
                            else:
                                for idx,fc in enumerate(from_cps):
                                    if idx < len(to_cps):
                                        translations[fc]=to_cps[idx]
                                    else:
                                        translations[fc]=to_cps[-1]
                    except:
                        pass
        return {'translations':translations,'flags':flags,'formatA':False}, None
    else:
        for line in lines:
            stripped=line.strip()
            if not stripped or stripped.startswith('#'):
                continue
            m=re.match(r'0x([0-9A-Fa-f]+)\s+0x([0-9A-Fa-f]+)', stripped)
            if m:
                try:
                    src=int(m.group(1),16)
                    dst=int(m.group(2),16)
                    translations[src]=dst
                except:
                    continue
        return {'translations':translations,'flags':flags,'formatA':True}, None

def trim_char(art, hardblank):
    leftmosts=[]
    rightmosts=[]
    for row in art:
        lm=len(row)
        for idx,ch in enumerate(row):
            if ch!=' ':
                lm=idx
                break
        leftmosts.append(lm)
        rm=-1
        for idx in range(len(row)-1,-1,-1):
            if row[idx]!=' ':
                rm=idx
                break
        rightmosts.append(rm)
    cl = min(leftmosts) if leftmosts else 0
    trailings=[]
    for row, rm in zip(art, rightmosts):
        if rm==-1:
            trailings.append(len(row))
        else:
            trailings.append(len(row)-1-rm)
    ct = min(trailings) if trailings else 0
    trimmed=[]
    for row in art:
        end = len(row)-ct if ct>0 else len(row)
        start = cl
        if start>len(row):
            trimmed.append("")
        else:
            trimmed.append(row[start:end] if start<=end else "")
    return trimmed

def leading_blanks(row):
    for i,ch in enumerate(row):
        if ch!=' ':
            return i
    return len(row)

def trailing_blanks(row):
    for i in range(len(row)-1,-1,-1):
        if row[i]!=' ':
            return len(row)-1-i
    return len(row)

def smush_pair(c1,c2,rules,hardblank):
    if c1==' ':
        return True,c2
    if c2==' ':
        return True,c1
    if c1==hardblank and c2==hardblank:
        if rules & SM_HARDBLANK:
            return True, hardblank
        return False,None
    if c1==hardblank or c2==hardblank:
        return False,None
    if c1==c2:
        if rules & SM_EQUAL:
            return True,c1
        return False,None
    if rules & SM_LOWLINE:
        if c1=='_':
            if c2 in "|/\\[]{}()<>":
                return True,c2
        if c2=='_':
            if c1 in "|/\\[]{}()<>":
                return True,c1
    if rules & SM_HIERARCHY:
        if c1 in _hierarchy and c2 in _hierarchy:
            if _hierarchy[c1]!=_hierarchy[c2]:
                return True, c1 if _hierarchy[c1]>_hierarchy[c2] else c2
    if rules & SM_PAIR:
        if (c1=='[' and c2==']') or (c1==']' and c2=='[') or (c1=='{' and c2=='}') or (c1=='}' and c2=='{') or (c1=='(' and c2==')') or (c1==')' and c2=='(') or (c1=='<' and c2=='>') or (c1=='>' and c2=='<'):
            return True,'|'
    if rules & SM_BIGX:
        if (c1=='/' and c2=='\\') or (c1=='\\' and c2=='/'):
            return True,'|'
        if (c1=='<' and c2=='>') or (c1=='>' and c2=='<'):
            return True,'X'
    return False,None

def smush_old(c1,c2,hardblank):
    if c1==' ':
        return True,c2
    if c2==' ':
        return True,c1
    if c1==hardblank and c2==hardblank:
        return True,hardblank
    if c1==hardblank or c2==hardblank:
        return False,None
    if c1==c2:
        return True,c1
    if c1=='_':
        if c2 in "|/\\[]{}()<>":
            return True,c2
    if c2=='_':
        if c1 in "|/\\[]{}()<>":
            return True,c1
    if c1 in _hierarchy and c2 in _hierarchy:
        if _hierarchy[c1]!=_hierarchy[c2]:
            return True, c1 if _hierarchy[c1]>_hierarchy[c2] else c2
    if (c1=='[' and c2==']') or (c1==']' and c2=='[') or (c1=='{' and c2=='}') or (c1=='}' and c2=='{') or (c1=='(' and c2==')') or (c1==')' and c2=='(') or (c1=='<' and c2=='>') or (c1=='>' and c2=='<'):
        return True,'|'
    if (c1=='/' and c2=='\\') or (c1=='\\' and c2=='/'):
        return True,'|'
    if (c1=='<' and c2=='>') or (c1=='>' and c2=='<'):
        return True,'X'
    return True,c2

def get_default_layout(font):
    full=font['full_layout']
    old=font['old_layout']
    if full!=0:
        low=full & 0xFF
        if low & 128:
            return 'SMUSH', low & 63
        elif low & 64:
            return 'KERN',0
        else:
            if low & 63:
                return 'SMUSH', low & 63
            else:
                return 'FULL',0
    if old==-1:
        return 'FULL',0
    elif old==0:
        return 'KERN',0
    elif old>0:
        return 'SMUSH',old
    else:
        return 'FULL',0

def compute_overlap(buf,new):
    m=None
    for b,n in zip(buf,new):
        tb=trailing_blanks(b)
        lb=leading_blanks(n)
        tot=tb+lb
        if m is None or tot<m:
            m=tot
    return 0 if m is None else m

def render_word(word,font,layout,rules):
    height=font['height']
    hb=font['hardblank']
    def get_art(cp):
        art=font['cmap'].get(cp)
        if art is None:
            art=font['cmap'].get(32)
            if art is None:
                art=[""]*height
        if layout=='FULL':
            return art
        return trim_char(art,hb)
    buf=["" for _ in range(height)]
    first=True
    for ch in word:
        cp=ord(ch)
        char_rows=get_art(cp)
        if first:
            buf=[r for r in char_rows]
            first=False
            continue
        cur_w=max(len(r) for r in buf)
        if layout=='FULL':
            new_buf=[]
            for i in range(height):
                brow=buf[i] if i < len(buf) else ""
                arow=char_rows[i] if i < len(char_rows) else ""
                new_buf.append(brow.ljust(cur_w)+arow)
            buf=new_buf
        elif layout=='KERN':
            ov=compute_overlap(buf,char_rows)
            new_w=cur_w + (max(len(r) for r in char_rows) if char_rows else 0) - ov
            new_buf=[]
            for i in range(height):
                brow=buf[i]
                arow=char_rows[i] if i < len(char_rows) else ""
                res=[' ']*new_w
                for j,chb in enumerate(brow):
                    if j<new_w:
                        res[j]=chb
                start=cur_w-ov
                for j,chn in enumerate(arow):
                    pos=start+j
                    if 0<=pos<new_w and chn!=' ':
                        res[pos]=chn
                new_buf.append(''.join(res))
            buf=new_buf
        elif layout=='OVERLAP':
            art2=char_rows
            w=max(len(r) for r in art2) if art2 else 0
            if w>1:
                art2=[row[1:] if row else "" for row in art2]
            ov=compute_overlap(buf,art2)
            new_w=cur_w + (max(len(r) for r in art2) if art2 else 0) - ov
            new_buf=[]
            for i in range(height):
                brow=buf[i]
                arow=art2[i] if i < len(art2) else ""
                res=[' ']*new_w
                for j,chb in enumerate(brow):
                    if j<new_w:
                        res[j]=chb
                start=cur_w-ov
                for j,chn in enumerate(arow):
                    pos=start+j
                    if 0<=pos<new_w and chn!=' ':
                        res[pos]=chn
                new_buf.append(''.join(res))
            buf=new_buf
        else: # SMUSH
            ov=compute_overlap(buf,char_rows)
            attempt=ov+1
            # check rows where overlap causes collision
            can=True
            infos=[]
            for i in range(height):
                brow=buf[i]
                arow=char_rows[i] if i < len(char_rows) else ""
                # compute rb and lb
                rb=-1
                for idx in range(len(brow)-1,-1,-1):
                    if brow[idx]!=' ':
                        rb=idx
                        break
                lb=len(arow)
                for idx,ch in enumerate(arow):
                    if ch!=' ':
                        lb=idx
                        break
                tb=trailing_blanks(brow)
                lb2=leading_blanks(arow)
                # if tb+lb2 < attempt => overlap exists? Actually need tb+lb2 < attempt? Let's use condition tb+lb2 < attempt => overlapping
                # For minimal overlap rows, tb+lb2 == ov, so attempt = ov+1 => tb+lb2 = ov < attempt => overlap by 1
                # So condition for overlap in this row: tb+lb2 < attempt ? Or <=? Let's check: if tb+lb2 == ov, then after attempt, new first non-space moves to rb (overlap by 1). So there is overlap of 1 column where both have non-space? Actually after attempt, new first non-space at rb, so overlapping column is rb where both have non-space.
                # So condition for needing smush check is tb+lb2 == ov (i.e., this row is minimal) -> it will have overlap after attempt
                # For rows where tb+lb2 > ov, no overlap after attempt (still gap) -> no smush needed
                if tb+lb2 == ov:
                    c1=brow[rb] if rb!=-1 else ' '
                    c2=arow[lb] if lb!=len(arow) else ' '
                    if layout=='SMUSH':
                        ok,rc=smush_pair(c1,c2,rules,hb)
                    else:
                        ok,rc=smush_old(c1,c2,hb)
                    if not ok:
                        can=False
                        break
                    infos.append((rb,lb,rc))
                else:
                    infos.append(None)
            if can:
                new_w=cur_w + (max(len(r) for r in char_rows) if char_rows else 0) - attempt
                new_buf=[]
                for i in range(height):
                    brow=buf[i]
                    arow=char_rows[i] if i < len(char_rows) else ""
                    res=[' ']*new_w
                    for j,chb in enumerate(brow):
                        if j<new_w:
                            res[j]=chb
                    start=cur_w-attempt
                    info=infos[i]
                    if info:
                        rb,lb,rc=info
                        if rb<new_w:
                            res[rb]=rc
                        for j in range(lb+1, len(arow)):
                            pos=start+j
                            if 0<=pos<new_w:
                                chn=arow[j]
                                if chn!=' ':
                                    res[pos]=chn
                    else:
                        for j,chn in enumerate(arow):
                            pos=start+j
                            if 0<=pos<new_w and chn!=' ':
                                res[pos]=chn
                    new_buf.append(''.join(res))
                buf=new_buf
            else:
                new_w=cur_w + (max(len(r) for r in char_rows) if char_rows else 0) - ov
                new_buf=[]
                for i in range(height):
                    brow=buf[i]
                    arow=char_rows[i] if i < len(char_rows) else ""
                    res=[' ']*new_w
                    for j,chb in enumerate(brow):
                        if j<new_w:
                            res[j]=chb
                    start=cur_w-ov
                    for j,chn in enumerate(arow):
                        pos=start+j
                        if 0<=pos<new_w and chn!=' ':
                            res[pos]=chn
                    new_buf.append(''.join(res))
                buf=new_buf
    return buf

def render_logical_line(log_line,font,width,justify,text_dir,layout,rules):
    height=font['height']
    hb=font['hardblank']
    if width==1:
        out=[]
        for ch in log_line:
            if ch==' ':
                continue
            cp=ord(ch)
            art=font['cmap'].get(cp)
            if art is None:
                art=font['cmap'].get(32)
                if art is None:
                    art=[""]*height
            if layout!='FULL':
                art=trim_char(art,hb)
            disp=[row.replace(hb,' ') for row in art]
            out.extend(disp)
        return out
    if log_line=="":
        return ["" for _ in range(height)]
    tokens=re.findall(r'\S+|\s+', log_line)
    final=[]
    cur_buf=["" for _ in range(height)]

    def flush():
        nonlocal cur_buf,final
        if not cur_buf or all(b=="" for b in cur_buf):
            return
        disp=[row.replace(hb,' ') for row in cur_buf]
        cur_w=max(len(r) for r in disp) if disp else 0
        lead=0
        if justify=='CENTER':
            lead=(width - cur_w)//2
        elif justify=='RIGHT':
            lead=width - cur_w
        elif justify=='LEFT':
            lead=0
        else:
            if text_dir=='RIGHT':
                lead=width - cur_w
            else:
                lead=0
        if lead<0:
            lead=0
        for r in disp:
            final.append(' '*lead + r)
        cur_buf=["" for _ in range(height)]

    def combine(buf,word):
        # returns new buf after adding word
        height=font['height']
        hb=font['hardblank']
        def get_art(cp):
            art=font['cmap'].get(cp)
            if art is None:
                art=font['cmap'].get(32)
                if art is None:
                    art=[""]*height
            if layout=='FULL':
                return art
            return trim_char(art,hb)
        tmp=[row for row in buf]
        for ch in word:
            cp=ord(ch)
            char_rows=get_art(cp)
            if not tmp or all(b=="" for b in tmp):
                tmp=[r for r in char_rows]
                continue
            cur_w=max(len(r) for r in tmp)
            if layout=='FULL':
                new_buf=[]
                for i in range(height):
                    brow=tmp[i] if i < len(tmp) else ""
                    arow=char_rows[i] if i < len(char_rows) else ""
                    new_buf.append(brow.ljust(cur_w)+arow)
                tmp=new_buf
            elif layout=='KERN':
                ov=compute_overlap(tmp,char_rows)
                new_w=cur_w + (max(len(r) for r in char_rows) if char_rows else 0) - ov
                new_buf=[]
                for i in range(height):
                    brow=tmp[i]
                    arow=char_rows[i] if i < len(char_rows) else ""
                    res=[' ']*new_w
                    for j,chb in enumerate(brow):
                        if j<new_w:
                            res[j]=chb
                    start=cur_w-ov
                    for j,chn in enumerate(arow):
                        pos=start+j
                        if 0<=pos<new_w and chn!=' ':
                            res[pos]=chn
                    new_buf.append(''.join(res))
                tmp=new_buf
            elif layout=='OVERLAP':
                art2=char_rows
                w=max(len(r) for r in art2) if art2 else 0
                if w>1:
                    art2=[row[1:] if row else "" for row in art2]
                ov=compute_overlap(tmp,art2)
                new_w=cur_w + (max(len(r) for r in art2) if art2 else 0) - ov
                new_buf=[]
                for i in range(height):
                    brow=tmp[i]
                    arow=art2[i] if i < len(art2) else ""
                    res=[' ']*new_w
                    for j,chb in enumerate(brow):
                        if j<new_w:
                            res[j]=chb
                    start=cur_w-ov
                    for j,chn in enumerate(arow):
                        pos=start+j
                        if 0<=pos<new_w and chn!=' ':
                            res[pos]=chn
                    new_buf.append(''.join(res))
                tmp=new_buf
            else:
                ov=compute_overlap(tmp,char_rows)
                attempt=ov+1
                can=True
                infos=[]
                for i in range(height):
                    brow=tmp[i]
                    arow=char_rows[i] if i < len(char_rows) else ""
                    tb=trailing_blanks(brow)
                    lb=leading_blanks(arow)
                    if tb+lb==ov:
                        rb=-1
                        for idx in range(len(brow)-1,-1,-1):
                            if brow[idx]!=' ':
                                rb=idx
                                break
                        lb_idx=len(arow)
                        for idx,ch in enumerate(arow):
                            if ch!=' ':
                                lb_idx=idx
                                break
                        c1=brow[rb] if rb!=-1 else ' '
                        c2=arow[lb_idx] if lb_idx!=len(arow) else ' '
                        if layout=='SMUSH':
                            ok,rc=smush_pair(c1,c2,rules,hb)
                        else:
                            ok,rc=smush_old(c1,c2,hb)
                        if not ok:
                            can=False
                            break
                        infos.append((rb,lb_idx,rc))
                    else:
                        infos.append(None)
                if can:
                    new_w=cur_w + (max(len(r) for r in char_rows) if char_rows else 0) - attempt
                    new_buf=[]
                    for i in range(height):
                        brow=tmp[i]
                        arow=char_rows[i] if i < len(char_rows) else ""
                        res=[' ']*new_w
                        for j,chb in enumerate(brow):
                            if j<new_w:
                                res[j]=chb
                        start=cur_w-attempt
                        info=infos[i]
                        if info:
                            rb,lb_idx,rc=info
                            if rb<new_w:
                                res[rb]=rc
                            for j in range(lb_idx+1,len(arow)):
                                pos=start+j
                                if 0<=pos<new_w:
                                    chn=arow[j]
                                    if chn!=' ':
                                        res[pos]=chn
                        else:
                            for j,chn in enumerate(arow):
                                pos=start+j
                                if 0<=pos<new_w and chn!=' ':
                                    res[pos]=chn
                        new_buf.append(''.join(res))
                    tmp=new_buf
                else:
                    new_w=cur_w + (max(len(r) for r in char_rows) if char_rows else 0) - ov
                    new_buf=[]
                    for i in range(height):
                        brow=tmp[i]
                        arow=char_rows[i] if i < len(char_rows) else ""
                        res=[' ']*new_w
                        for j,chb in enumerate(brow):
                            if j<new_w:
                                res[j]=chb
                        start=cur_w-ov
                        for j,chn in enumerate(arow):
                            pos=start+j
                            if 0<=pos<new_w and chn!=' ':
                                res[pos]=chn
                        new_buf.append(''.join(res))
                    tmp=new_buf
        return tmp

    for token in tokens:
        if token.isspace():
            if all(b=="" for b in cur_buf):
                continue
            # add spaces one by one
            for _ in range(len(token)):
                cp=32
                art=font['cmap'].get(cp)
                if art is None:
                    art=[""]*height
                char_rows = art if layout=='FULL' else trim_char(art,font['hardblank'])
                cur_w = max(len(r) for r in cur_buf) if cur_buf else 0
                ov = 0 if layout=='FULL' else compute_overlap(cur_buf, char_rows)
                new_w = cur_w + (max(len(r) for r in char_rows) if char_rows else 0) - ov
                if new_w > width:
                    flush()
                    break
                else:
                    cur_buf = combine(cur_buf, ' ')
        else:
            word_buf = render_word(token,font,layout,rules)
            if all(b=="" for b in cur_buf):
                cur_buf = word_buf
                continue
            tentative = combine(cur_buf, token)
            tent_w = max(len(r) for r in tentative) if tentative else 0
            if tent_w > width:
                flush()
                cur_buf = word_buf
            else:
                cur_buf = tentative
    if not all(b=="" for b in cur_buf):
        disp=[row.replace(hb,' ') for row in cur_buf]
        cur_w=max(len(r) for r in disp) if disp else 0
        lead=0
        if justify=='CENTER':
            lead=(width - cur_w)//2
        elif justify=='RIGHT':
            lead=width - cur_w
        elif justify=='LEFT':
            lead=0
        else:
            if text_dir=='RIGHT':
                lead=width - cur_w
            else:
                lead=0
        if lead<0:
            lead=0
        for r in disp:
            final.append(' '*lead + r)
    return final

def main():
    prog=os.path.basename(sys.argv[0])
    fontdir=None
    fontname=DEFAULT_FONT
    width=80
    smush_mode=None
    explicit_layout=None
    justify='X'
    text_dir='X'
    deutsch=False
    controls=[]
    infocode=None
    v_flag=False
    para_mode='NORMAL'

    valid_no_arg=set(list("cklnoprstvxDELNRSWX"))
    valid_arg=set(['d','f','m','w','C','I'])
    args=sys.argv[1:]
    i=0
    msg_parts=[]

    while i < len(args):
        arg=args[i]
        if arg=='--':
