        uniq=[]
        seen=set()
        for d in dirs:
            if d not in seen:
                seen.add(d)
                uniq.append(d)
        for d in uniq:
            for cand in with_exts(os.path.join(d, ctrlname)):
                r=try_path(cand)
                if r:
