        if c1=='_':
            if c2 in "|/\\[]{}()<>":
                return True,c2
        if c2=='_':
            if c1 in "|/\\[]{}()<>":
                return True,c1
    if rules & SM_HIERARCHY:
        if c1 in _hierarchy and c2 in _hierarchy:
            if _hierarchy[c1]!=_hierarchy[c2]:
                return True, c1 if _hierarchy[c1]>_hierarchy[c2] else c2
    if rules & SM_PAIR:
        if (c1=='[' and c2==']') or (c1==']' and c2=='[') or (c1=='{' and c2=='}') or (c1=='}' and c2=='{') or (c1=='(' and c2==')') or (c1==')' and c2=='(') or (c1=='<' and c2=='>') or (c1=='>' and c2=='<'):
            return True,'|'
    if rules & SM_BIGX:
        if (c1=='/' and c2=='\\') or (c1=='\\' and c2=='/'):
            return True,'|'
        if (c1=='<' and c2=='>') or (c1=='>' and c2=='<'):
            return True,'X'
    return False,None

def smush_old(c1,c2,hardblank):
    if c1==' ':
        return True,c2
    if c2==' ':
        return True,c1
    if c1==hardblank and c2==hardblank:
        return True,hardblank
    if c1==hardblank or c2==hardblank:
        return False,None
    if c1==c2:
        return True,c1
    if c1=='_':
        if c2 in "|/\\[]{}()<>":
            return True,c2
    if c2=='_':
        if c1 in "|/\\[]{}()<>":
            return True,c1
    if c1 in _hierarchy and c2 in _hierarchy:
        if _hierarchy[c1]!=_hierarchy[c2]:
            return True, c1 if _hierarchy[c1]>_hierarchy[c2] else c2
    if (c1=='[' and c2==']') or (c1==']' and c2=='[') or (c1=='{' and c2=='}') or (c1=='}' and c2=='{') or (c1=='(' and c2==')') or (c1==')' and c2=='(') or (c1=='<' and c2=='>') or (c1=='>' and c2=='<'):
        return True,'|'
    if (c1=='/' and c2=='\\') or (c1=='\\' and c2=='/'):
        return True,'|'
    if (c1=='<' and c2=='>') or (c1=='>' and c2=='<'):
        return True,'X'
    return True,c2

def get_default_layout(font):
    full=font['full_layout']
    old=font['old_layout']
    if full!=0:
        low=full & 0xFF
        if low & 128:
            return 'SMUSH', low & 63
        elif low & 64:
            return 'KERN',0
        else:
            if low & 63:
                return 'SMUSH', low & 63
            else:
                return 'FULL',0
    if old==-1:
        return 'FULL',0
    elif old==0:
        return 'KERN',0
    elif old>0:
        return 'SMUSH',old
    else:
        return 'FULL',0

def compute_overlap(buf,new):
    m=None
    for b,n in zip(buf,new):
        tb=trailing_blanks(b)
        lb=leading_blanks(n)
        tot=tb+lb
        if m is None or tot<m:
            m=tot
    return 0 if m is None else m

def render_word(word,font,layout,rules):
    height=font['height']
    def get_art(cp):
        art=font['cmap'].get(cp)
        if art is None:
            art=font['cmap'].get(32)
            if art is None:
                art=[""]*height
        if layout=='FULL':
            return art
        return trim_char(art,font['hardblank'])
    buf=["" for _ in range(height)]
    first=True
    for ch in word:
        cp=ord(ch)
        char_rows=get_art(cp)
        if first:
            buf=[r for r in char_rows]
            first=False
            continue
        cur_w=max(len(r) for r in buf)
        if layout=='FULL':
            new_buf=[]
            for i in range(height):
                brow=buf[i] if i < len(buf) else ""
                arow=char_rows[i] if i < len(char_rows) else ""
                new_buf.append(brow.ljust(cur_w)+arow)
            buf=new_buf
        elif layout=='KERN':
            ov=compute_overlap(buf,char_rows)
            new_w=cur_w + (max(len(r) for r in char_rows) if char_rows else 0) - ov
            new_buf=[]
            for i in range(height):
                brow=buf[i]
                arow=char_rows[i] if i < len(char_rows) else ""
                res=[' ']*new_w
                for j,chb in enumerate(brow):
                    if j<new_w:
                        res[j]=chb
                start=cur_w-ov
                for j,chn in enumerate(arow):
                    pos=start+j
                    if 0<=pos<new_w and chn!=' ':
                        res[pos]=chn
                new_buf.append(''.join(res))
            buf=new_buf
        elif layout=='OVERLAP':
            art2=char_rows
            w=max(len(r) for r in art2) if art2 else 0
            if w>1:
                art2=[row[1:] if row else "" for row in art2]
            ov=compute_overlap(buf,art2)
            new_w=cur_w + (max(len(r) for r in art2) if art2 else 0) - ov
            new_buf=[]
            for i in range(height):
                brow=buf[i]
                arow=art2[i] if i < len(art2) else ""
                res=[' ']*new_w
                for j,chb in enumerate(brow):
                    if j<new_w:
                        res[j]=chb
                start=cur_w-ov
                for j,chn in enumerate(arow):
                    pos=start+j
                    if 0<=pos<new_w and chn!=' ':
                        res[pos]=chn
                new_buf.append(''.join(res))
            buf=new_buf
        else:
            ov=compute_overlap(buf,char_rows)
            attempt=ov+1
            can=True
            infos=[]
            for i in range(height):
                brow=buf[i]
                arow=char_rows[i] if i < len(char_rows) else ""
                tb=trailing_blanks(brow)
                lb=leading_blanks(arow)
                if tb+lb==ov:
                    rb=-1
                    for idx in range(len(brow)-1,-1,-1):
                        if brow[idx]!=' ':
                            rb=idx
                            break
                    lb_idx=len(arow)
                    for idx,ch in enumerate(arow):
                        if ch!=' ':
                            lb_idx=idx
                            break
                    if rb==-1 or lb_idx==len(arow):
                        infos.append(None)
                        continue
                    c1=brow[rb]
                    c2=arow[lb_idx]
                    if layout=='SMUSH':
                        ok,rc=smush_pair(c1,c2,rules,font['hardblank'])
                    else:
                        ok,rc=smush_old(c1,c2,font['hardblank'])
                    if not ok:
                        can=False
                        break
                    infos.append((rb,lb_idx,rc))
                else:
                    infos.append(None)
            if can:
                new_w=cur_w + (max(len(r) for r in char_rows) if char_rows else 0) - attempt
                new_buf=[]
                for i in range(height):
                    brow=buf[i]
                    arow=char_rows[i] if i < len(char_rows) else ""
                    res=[' ']*new_w
                    for j,chb in enumerate(brow):
                        if j<new_w:
                            res[j]=chb
                    start=cur_w-attempt
                    info=infos[i]
                    if info:
                        rb,lb_idx,rc=info
                        if rb<new_w:
                            res[rb]=rc
                        for j in range(lb_idx+1,len(arow)):
                            pos=start+j
                            if 0<=pos<new_w:
                                chn=arow[j]
                                if chn!=' ':
                                    res[pos]=chn
                    else:
                        for j,chn in enumerate(arow):
                            pos=start+j
                            if 0<=pos<new_w and chn!=' ':
                                res[pos]=chn
                    new_buf.append(''.join(res))
                buf=new_buf
            else:
                new_w=cur_w + (max(len(r) for r in char_rows) if char_rows else 0) - ov
                new_buf=[]
                for i in range(height):
                    brow=buf[i]
                    arow=char_rows[i] if i < len(char_rows) else ""
                    res=[' ']*new_w
                    for j,chb in enumerate(brow):
                        if j<new_w:
                            res[j]=chb
                    start=cur_w-ov
                    for j,chn in enumerate(arow):
                        pos=start+j
                        if 0<=pos<new_w and chn!=' ':
                            res[pos]=chn
                    new_buf.append(''.join(res))
                buf=new_buf
    return buf

def render_logical_line(log_line,font,width,justify,text_dir,layout,rules):
    height=font['height']
    hb=font['hardblank']
    if width==1:
        out=[]
        for ch in log_line:
            if ch==' ':
                continue
            cp=ord(ch)
            art=font['cmap'].get(cp)
            if art is None:
                art=font['cmap'].get(32)
                if art is None:
                    art=[""]*height
            if layout!='FULL':
                art=trim_char(art,hb)
            disp=[row.replace(hb,' ') for row in art]
            out.extend(disp)
        return out
    if log_line=="":
        return ["" for _ in range(height)]
    tokens=re.findall(r'\S+|\s+', log_line)
    final=[]
    cur_buf=["" for _ in range(height)]

    def flush():
        nonlocal cur_buf,final
        if not cur_buf or all(b=="" for b in cur_buf):
            return
        disp=[row.replace(hb,' ') for row in cur_buf]
        cur_w=max(len(r) for r in disp) if disp else 0
        lead=0
        if justify=='CENTER':
            lead=(width - cur_w)//2
        elif justify=='RIGHT':
            lead=width - cur_w
        elif justify=='LEFT':
            lead=0
        else:
            lead=width - cur_w if text_dir=='RIGHT' else 0
        if lead<0:
            lead=0
        for r in disp:
            final.append(' '*lead + r)
        cur_buf=["" for _ in range(height)]

    def combine(buf,word):
        height=font['height']
        hb=font['hardblank']
        def get_art(cp):
            art=font['cmap'].get(cp)
            if art is None:
                art=font['cmap'].get(32)
                if art is None:
                    art=[""]*height
            if layout=='FULL':
                return art
            return trim_char(art,hb)
        tmp=[row for row in buf]
        for ch in word:
            cp=ord(ch)
            char_rows=get_art(cp)
            if not tmp or all(b=="" for b in tmp):
                tmp=[r for r in char_rows]
                continue
            cur_w=max(len(r) for r in tmp)
            if layout=='FULL':
                new_buf=[]
                for i in range(height):
                    brow=tmp[i] if i<len(tmp) else ""
                    arow=char_rows[i] if i<len(char_rows) else ""
                    new_buf.append(brow.ljust(cur_w)+arow)
                tmp=new_buf
            elif layout=='KERN':
                ov=compute_overlap(tmp,char_rows)
                new_w=cur_w + (max(len(r) for r in char_rows) if char_rows else 0) - ov
                new_buf=[]
                for i in range(height):
                    brow=tmp[i]
                    arow=char_rows[i] if i<len(char_rows) else ""
                    res=[' ']*new_w
                    for j,chb in enumerate(brow):
                        if j<new_w:
                            res[j]=chb
                    start=cur_w-ov
                    for j,chn in enumerate(arow):
                        pos=start+j
                        if 0<=pos<new_w and chn!=' ':
                            res[pos]=chn
                    new_buf.append(''.join(res))
                tmp=new_buf
            elif layout=='OVERLAP':
                art2=char_rows
                w=max(len(r) for r in art2) if art2 else 0
                if w>1:
                    art2=[row[1:] if row else "" for row in art2]
                ov=compute_overlap(tmp,art2)
                new_w=cur_w + (max(len(r) for r in art2) if art2 else 0) - ov
                new_buf=[]
                for i in range(height):
                    brow=tmp[i]
                    arow=art2[i] if i<len(art2) else ""
                    res=[' ']*new_w
                    for j,chb in enumerate(brow):
                        if j<new_w:
                            res[j]=chb
                    start=cur_w-ov
                    for j,chn in enumerate(arow):
                        pos=start+j
                        if 0<=pos<new_w and chn!=' ':
                            res[pos]=chn
                    new_buf.append(''.join(res))
                tmp=new_buf
            else:
                ov=compute_overlap(tmp,char_rows)
                attempt=ov+1
                can=True
                infos=[]
                for i in range(height):
                    brow=tmp[i]
                    arow=char_rows[i] if i<len(char_rows) else ""
                    tb=trailing_blanks(brow)
                    lb=leading_blanks(arow)
                    if tb+lb==ov:
                        rb=-1
                        for idx in range(len(brow)-1,-1,-1):
                            if brow[idx]!=' ':
                                rb=idx
                                break
                        lb_idx=len(arow)
                        for idx,ch in enumerate(arow):
                            if ch!=' ':
                                lb_idx=idx
                                break
                        c1=brow[rb] if rb!=-1 else ' '
                        c2=arow[lb_idx] if lb_idx!=len(arow) else ' '
                        if layout=='SMUSH':
                            ok,rc=smush_pair(c1,c2,rules,hb)
                        else:
                            ok,rc=smush_old(c1,c2,hb)
                        if not ok:
                            can=False
                            break
                        infos.append((rb,lb_idx,rc))
                    else:
                        infos.append(None)
                if can:
                    new_w=cur_w + (max(len(r) for r in char_rows) if char_rows else 0) - attempt
                    new_buf=[]
                    for i in range(height):
                        brow=tmp[i]
                        arow=char_rows[i] if i<len(char_rows) else ""
                        res=[' ']*new_w
                        for j,chb in enumerate(brow):
                            if j<new_w:
                                res[j]=chb
                        start=cur_w-attempt
                        info=infos[i]
                        if info:
                            rb,lb_idx,rc=info
                            if rb<new_w:
                                res[rb]=rc
                            for j in range(lb_idx+1,len(arow)):
                                pos=start+j
                                if 0<=pos<new_w:
                                    chn=arow[j]
                                    if chn!=' ':
                                        res[pos]=chn
                        else:
                            for j,chn in enumerate(arow):
                                pos=start+j
                                if 0<=pos<new_w and chn!=' ':
                                    res[pos]=chn
                        new_buf.append(''.join(res))
                    tmp=new_buf
                else:
                    new_w=cur_w + (max(len(r) for r in char_rows) if char_rows else 0) - ov
                    new_buf=[]
                    for i in range(height):
                        brow=tmp[i]
                        arow=char_rows[i] if i<len(char_rows) else ""
                        res=[' ']*new_w
                        for j,chb in enumerate(brow):
                            if j<new_w:
                                res[j]=chb
                        start=cur_w-ov
                        for j,chn in enumerate(arow):
                            pos=start+j
                            if 0<=pos<new_w and chn!=' ':
                                res[pos]=chn
                        new_buf.append(''.join(res))
                    tmp=new_buf
        return tmp

    for token in tokens:
        if token.isspace():
            if all(b=="" for b in cur_buf):
                continue
            for _ in range(len(token)):
                cp=32
                art=font['cmap'].get(cp)
                if art is None:
                    art=[""]*height
                char_rows = art if layout=='FULL' else trim_char(art,hb)
                cur_w = max(len(r) for r in cur_buf) if cur_buf else 0
                ov = 0 if layout=='FULL' else compute_overlap(cur_buf, char_rows)
                new_w = cur_w + (max(len(r) for r in char_rows) if char_rows else 0) - ov
                if new_w > width:
                    flush()
                    break
                else:
                    cur_buf = combine(cur_buf, ' ')
        else:
            word_buf = render_word(token,font,layout,rules)
            if all(b=="" for b in cur_buf):
                cur_buf = word_buf
                continue
            tentative = combine(cur_buf, token)
            tent_w = max(len(r) for r in tentative) if tentative else 0
            if tent_w > width:
                flush()
                cur_buf = word_buf
            else:
                cur_buf = tentative

    if not all(b=="" for b in cur_buf):
        disp=[row.replace(hb,' ') for row in cur_buf]
        cur_w=max(len(r) for r in disp) if disp else 0
        lead=0
        if justify=='CENTER':
            lead=(width - cur_w)//2
        elif justify=='RIGHT':
            lead=width - cur_w
        elif justify=='LEFT':
            lead=0
        else:
            lead=width - cur_w if text_dir=='RIGHT' else 0
        if lead<0:
            lead=0
        for r in disp:
            final.append(' '*lead + r)
    return final

