            smush_rules=smush_mode if smush_mode is not None else 0

    font_print_dir=font_data['print_dir']
    if text_dir=='X':
        effective_dir='RIGHT' if font_print_dir==1 else 'LEFT'
    elif text_dir=='LEFT':
