    else:
        data=sys.stdin.read()
        data=data.replace('\r','\n').replace('\x0b','\n').replace('\x0c','\n').replace('\t',' ')
        if para_mode=='PARA':
            res=[]
            for idx,ch in enumerate(data):
                if ch=='\n':
                    prev=data[idx-1] if idx>0 else '\n'
                    nxt=data[idx+1] if idx+1 < len(data) else '\n'
