            lead=width - cur_w
        elif justify=='LEFT':
            lead=0
        else:
            lead=width - cur_w if text_dir=='RIGHT' else 0
        if lead<0:
            lead=0
        for r in disp:
            final.append(' '*lead + r)
    return final

