                    tmp=new_buf
        return tmp

    words=log_line.split()
    # If original line had leading/trailing spaces, split() loses them, but we earlier skip leading spaces anyway (original does not start line with spaces). So using split() is okay for wrapping?

    for word in words:
        # If cur_buf empty, we try to place word even if exceeds
