                if len(parts)<2:
                    continue
                from_cps=expand_control_token(parts[0])
                to_cps=expand_control_token(parts[1])
                if not from_cps or not to_cps:
                    continue
                if len(to_cps)==1:
                    for fc in from_cps:
                        trans[fc]=to_cps[0]
                else:
                    for idx,fc in enumerate(from_cps):
                        trans[fc]=to_cps[idx] if idx < len(to_cps) else to_cps[-1]
            elif cmd=='u':
                flags['utf8']=True
            else:
                parts=stripped.split()
                if len(parts)>=2:
                    try:
                        from_cps=expand_control_token(parts[0])
                        to_cps=expand_control_token(parts[1])
                        if from_cps and to_cps:
                            if len(to_cps)==1:
                                for fc in from_cps:
                                    trans[fc]=to_cps[0]
                            else:
                                for idx,fc in enumerate(from_cps):
                                    trans[fc]=to_cps[idx] if idx < len(to_cps) else to_cps[-1]
                    except:
                        pass
        return {'translations':trans,'flags':flags,'formatA':False},None
    else:
        for line in lines:
            stripped=line.strip()
            if not stripped or stripped.startswith('#'):
                continue
            m=re.match(r'0x([0-9A-Fa-f]+)\s+0x([0-9A-Fa-f]+)',stripped)
            if m:
                try:
                    src=int(m.group(1),16)
                    dst=int(m.group(2),16)
                    trans[src]=dst
                except:
                    continue
        return {'translations':trans,'flags':flags,'formatA':True},None

def trim_char(art,hb):
    lefts=[]
    rights=[]
    for row in art:
        lm=len(row)
        for idx,ch in enumerate(row):
            if ch!=' ':
                lm=idx
                break
        lefts.append(lm)
        rm=-1
        for idx in range(len(row)-1,-1,-1):
            if row[idx]!=' ':
                rm=idx
                break
        rights.append(rm)
    cl=min(lefts) if lefts else 0
    trail=[]
    for row,rm in zip(art,rights):
        if rm==-1:
            trail.append(len(row))
        else:
            trail.append(len(row)-1-rm)
    ct=min(trail) if trail else 0
    res=[]
    for row in art:
        end=len(row)-ct if ct>0 else len(row)
        start=cl
        if start>len(row):
            res.append("")
        else:
            res.append(row[start:end] if start<=end else "")
    return res

def leading_blanks(row):
    for i,ch in enumerate(row):
        if ch!=' ':
            return i
    return len(row)
def trailing_blanks(row):
    for i in range(len(row)-1,-1,-1):
        if row[i]!=' ':
            return len(row)-1-i
    return len(row)

def smush_pair(c1,c2,rules,hb):
    if c1==' ':
        return True,c2
    if c2==' ':
        return True,c1
    if c1==hb and c2==hb:
        return (True,hb) if (rules & SM_HARDBLANK) else (False,None)
    if c1==hb or c2==hb:
        return False,None
    if c1==c2:
        return (True,c1) if (rules & SM_EQUAL) else (False,None)
    if rules & SM_LOWLINE:
        if c1=='_':
            if c2 in "|/\\[]{}()<>":
                return True,c2
        if c2=='_':
            if c1 in "|/\\[]{}()<>":
                return True,c1
    if rules & SM_HIERARCHY:
        if c1 in _hierarchy and c2 in _hierarchy and _hierarchy[c1]!=_hierarchy[c2]:
            return True, c1 if _hierarchy[c1]>_hierarchy[c2] else c2
    if rules & SM_PAIR:
        if (c1=='[' and c2==']') or (c1==']' and c2=='[') or (c1=='{' and c2=='}') or (c1=='}' and c2=='{') or (c1=='(' and c2==')') or (c1==')' and c2=='(') or (c1=='<' and c2=='>') or (c1=='>' and c2=='<'):
            return True,'|'
    if rules & SM_BIGX:
        if (c1=='/' and c2=='\\') or (c1=='\\' and c2=='/'):
            return True,'|'
        if (c1=='<' and c2=='>') or (c1=='>' and c2=='<'):
            return True,'X'
    return False,None

def smush_old(c1,c2,hb):
    if c1==' ':
        return True,c2
    if c2==' ':
        return True,c1
    if c1==hb and c2==hb:
        return True,hb
    if c1==hb or c2==hb:
        return False,None
    if c1==c2:
        return True,c1
    if c1=='_':
        if c2 in "|/\\[]{}()<>":
            return True,c2
    if c2=='_':
        if c1 in "|/\\[]{}()<>":
            return True,c1
    if c1 in _hierarchy and c2 in _hierarchy and _hierarchy[c1]!=_hierarchy[c2]:
        return True, c1 if _hierarchy[c1]>_hierarchy[c2] else c2
    if (c1=='[' and c2==']') or (c1==']' and c2=='[') or (c1=='{' and c2=='}') or (c1=='}' and c2=='{') or (c1=='(' and c2==')') or (c1==')' and c2=='(') or (c1=='<' and c2=='>') or (c1=='>' and c2=='<'):
        return True,'|'
    if (c1=='/' and c2=='\\') or (c1=='\\' and c2=='/'):
        return True,'|'
    if (c1=='<' and c2=='>') or (c1=='>' and c2=='<'):
        return True,'X'
    return True,c2

def get_default_layout(font):
    full=font['full_layout']
    old=font['old_layout']
    if full!=0:
        low=full & 0xFF
        if low & 128:
            return 'SMUSH', low & 63
        elif low & 64:
            return 'KERN',0
        else:
            if low & 63:
                return 'SMUSH', low & 63
            return 'FULL',0
    if old==-1:
        return 'FULL',0
    elif old==0:
        return 'KERN',0
    elif old>0:
        return 'SMUSH',old
    else:
        return 'FULL',0

def compute_overlap(buf,new):
    m=None
    for b,n in zip(buf,new):
        tot=trailing_blanks(b)+leading_blanks(n)
        if m is None or tot<m:
            m=tot
    return 0 if m is None else m

def render_word(word,font,layout,rules):
    height=font['height']
    def get_art(cp):
        art=font['cmap'].get(cp)
        if art is None:
            art=font['cmap'].get(32)
            if art is None:
                art=[""]*height
        return art if layout=='FULL' else trim_char(art,font['hardblank'])
    buf=["" for _ in range(height)]
    first=True
    for ch in word:
        cp=ord(ch)
        char_rows=get_art(cp)
        if first:
            buf=[r for r in char_rows]
            first=False
            continue
        cur_w=max(len(r) for r in buf)
        if layout=='FULL':
            buf=[buf[i].ljust(cur_w)+(char_rows[i] if i < len(char_rows) else "") for i in range(height)]
        elif layout=='KERN':
            ov=compute_overlap(buf,char_rows)
            new_w=cur_w + (max(len(r) for r in char_rows) if char_rows else 0) - ov
            new_buf=[]
            for i in range(height):
                brow=buf[i]
                arow=char_rows[i] if i < len(char_rows) else ""
                res=[' ']*new_w
                for j,chb in enumerate(brow):
                    if j<new_w:
                        res[j]=chb
                start=cur_w-ov
                for j,chn in enumerate(arow):
                    pos=start+j
                    if 0<=pos<new_w and chn!=' ':
                        res[pos]=chn
                new_buf.append(''.join(res))
            buf=new_buf
        elif layout=='OVERLAP':
            art2=char_rows
            w=max(len(r) for r in art2) if art2 else 0
            if w>1:
                art2=[row[1:] if row else "" for row in art2]
            ov=compute_overlap(buf,art2)
            new_w=cur_w + (max(len(r) for r in art2) if art2 else 0) - ov
            new_buf=[]
            for i in range(height):
                brow=buf[i]
                arow=art2[i] if i < len(art2) else ""
                res=[' ']*new_w
                for j,chb in enumerate(brow):
                    if j<new_w:
                        res[j]=chb
                start=cur_w-ov
                for j,chn in enumerate(arow):
                    pos=start+j
                    if 0<=pos<new_w and chn!=' ':
                        res[pos]=chn
                new_buf.append(''.join(res))
            buf=new_buf
        else:
            ov=compute_overlap(buf,char_rows)
            attempt=ov+1
            can=True
            infos=[]
            for i in range(height):
                brow=buf[i]
                arow=char_rows[i] if i < len(char_rows) else ""
                tb=trailing_blanks(brow)
                lb=leading_blanks(arow)
                if tb+lb==ov:
                    rb=-1
                    for idx in range(len(brow)-1,-1,-1):
                        if brow[idx]!=' ':
                            rb=idx
                            break
                    lb_idx=len(arow)
                    for idx,ch in enumerate(arow):
                        if ch!=' ':
                            lb_idx=idx
                            break
                    if rb==-1 or lb_idx==len(arow):
                        infos.append(None)
                        continue
                    c1=brow[rb]
                    c2=arow[lb_idx]
                    if layout=='SMUSH':
                        ok,rc=smush_pair(c1,c2,rules,font['hardblank'])
                    else:
                        ok,rc=smush_old(c1,c2,font['hardblank'])
                    if not ok:
                        can=False
                        break
                    infos.append((rb,lb_idx,rc))
                else:
                    infos.append(None)
            if can:
                new_w=cur_w + (max(len(r) for r in char_rows) if char_rows else 0) - attempt
                new_buf=[]
                for i in range(height):
                    brow=buf[i]
                    arow=char_rows[i] if i < len(char_rows) else ""
                    res=[' ']*new_w
                    for j,chb in enumerate(brow):
                        if j<new_w:
                            res[j]=chb
                    start=cur_w-attempt
                    info=infos[i]
                    if info:
                        rb,lb_idx,rc=info
                        if rb<new_w:
                            res[rb]=rc
                        for j in range(lb_idx+1,len(arow)):
                            pos=start+j
                            if 0<=pos<new_w:
                                chn=arow[j]
                                if chn!=' ':
                                    res[pos]=chn
                    else:
                        for j,chn in enumerate(arow):
                            pos=start+j
                            if 0<=pos<new_w and chn!=' ':
                                res[pos]=chn
                    new_buf.append(''.join(res))
                buf=new_buf
            else:
                new_w=cur_w + (max(len(r) for r in char_rows) if char_rows else 0) - ov
                new_buf=[]
                for i in range(height):
                    brow=buf[i]
                    arow=char_rows[i] if i < len(char_rows) else ""
                    res=[' ']*new_w
                    for j,chb in enumerate(brow):
                        if j<new_w:
                            res[j]=chb
                    start=cur_w-ov
                    for j,chn in enumerate(arow):
                        pos=start+j
                        if 0<=pos<new_w and chn!=' ':
                            res[pos]=chn
                    new_buf.append(''.join(res))
                buf=new_buf
    return buf

def render_logical_line(log_line,font,width,justify,text_dir,layout,rules):
    height=font['height']
    hb=font['hardblank']
    if width==1:
        out=[]
        for ch in log_line:
            if ch==' ':
                continue
            cp=ord(ch)
            art=font['cmap'].get(cp)
            if art is None:
                art=font['cmap'].get(32)
                if art is None:
                    art=[""]*height
            if layout!='FULL':
                art=trim_char(art,hb)
            disp=[row.replace(hb,' ') for row in art]
            out.extend(disp)
        return out
    if log_line=="":
        return ["" for _ in range(height)]

    # Split into words for wrapping: \S+|\s+
    # We'll process using word-based wrapping
    # First, get list of words (non-space) and spaces
    # For wrapping, we need to handle words that themselves exceed width -> they must be broken char by char

    # Helper to render a sequence of characters (word) and get width
    def word_width(word):
        b=render_word(word,font,layout,rules)
        return max(len(r) for r in b) if b else 0

    # Tokenize preserving words and spaces? For our word wrapping, we will extract words (split by whitespace)
    # Actually we need to keep spaces as separators but for simplicity we will split line into words by spaces (any whitespace)
    # and then attempt to build physical lines word by word

    # Get words = log_line.split() ? That collapses multiple spaces, but we observed multiple spaces increase width by 1 per space, so we should preserve count? For simplicity we split into words and single spaces? Let's use re.findall as before for words only for width logic, but for rendering we need to include spaces between words.

    # For word wrapping, we will process words list = log_line.split()  (splits on any whitespace, collapses)
    # But this loses multiple spaces. However earlier test with multiple spaces "A  B" width 18 vs "A B" 17 shows multiple spaces increase width. So collapsing would lose that. But for wrapping with default width 80, multiple spaces still matter? Maybe we should use split(' ') to keep empty words for multiple spaces? Simpler: Use split(' ') to keep empties? That would give ["A","","B"] for "A  B". The empty strings between would correspond to extra spaces? Hmm.

    # For simplicity for wrapping, we will treat the logical line as sequence of characters and do char-by-char wrapping that respects word boundaries: we will try to add characters one by one, but when we encounter a space, we check if adding the next word would exceed?

    # Let's implement word-based wrapping as:

    # - Split log_line into words = log_line.split()  (this collapses spaces, but we will treat single space between words)
    # - For each word, if word fits in width, try to add to current physical line
    # - If word does NOT fit (its width > width), then it must be broken into characters (char-by-char) across multiple physical lines

    # Actually for "Hello World" width 20, words are ["Hello","World"]. Hello width 22 >20, so it does NOT fit, so it must be broken. World width 29 >20, also broken. So word-based alone would still need to break words.

    # So we need two-level: If word width <= width, treat as atomic. If word width > width, break word char by char.

    # Implementation steps for logical line:

    final=[]
    cur_buf=["" for _ in range(height)]
    cur_word_list=[] # not needed

    def flush():
        nonlocal cur_buf,final
        if not cur_buf or all(b=="" for b in cur_buf):
            return
        disp=[row.replace(hb,' ') for row in cur_buf]
        cur_w=max(len(r) for r in disp) if disp else 0
        lead=0
        if justify=='CENTER':
            lead=(width - cur_w)//2
        elif justify=='RIGHT':
            lead=width - cur_w
        elif justify=='LEFT':
            lead=0
        else:
            lead=width - cur_w if text_dir=='RIGHT' else 0
        if lead<0:
            lead=0
        for r in disp:
            final.append(' '*lead + r)
        cur_buf=["" for _ in range(height)]

    def combine(buf,word):
        # returns new buf after adding word (word is string, may contain spaces? but we will call with single word without spaces)
        # For this we can reuse render_word logic that adds chars sequentially to existing buf
        # We'll have a helper that adds a word to existing buffer (like render_word_combined)
        tmp=[row for row in buf]
        height=font['height']
        hb=font['hardblank']
        def get_art(cp):
            art=font['cmap'].get(cp)
            if art is None:
                art=font['cmap'].get(32)
                if art is None:
                    art=[""]*height
            return art if layout=='FULL' else trim_char(art,hb)
        for ch in word:
            cp=ord(ch)
            char_rows=get_art(cp)
            if not tmp or all(b=="" for b in tmp):
                tmp=[r for r in char_rows]
                continue
            cur_w=max(len(r) for r in tmp)
            if layout=='FULL':
                tmp=[tmp[i].ljust(cur_w)+(char_rows[i] if i < len(char_rows) else "") for i in range(height)]
            elif layout=='KERN':
                ov=compute_overlap(tmp,char_rows)
                new_w=cur_w + (max(len(r) for r in char_rows) if char_rows else 0) - ov
                new_buf=[]
                for i in range(height):
                    brow=tmp[i]
                    arow=char_rows[i] if i < len(char_rows) else ""
                    res=[' ']*new_w
                    for j,chb in enumerate(brow):
                        if j<new_w:
                            res[j]=chb
                    start=cur_w-ov
                    for j,chn in enumerate(arow):
                        pos=start+j
                        if 0<=pos<new_w and chn!=' ':
                            res[pos]=chn
                    new_buf.append(''.join(res))
                tmp=new_buf
            elif layout=='OVERLAP':
                art2=char_rows
                w=max(len(r) for r in art2) if art2 else 0
                if w>1:
                    art2=[row[1:] if row else "" for row in art2]
                ov=compute_overlap(tmp,art2)
                new_w=cur_w + (max(len(r) for r in art2) if art2 else 0) - ov
                new_buf=[]
                for i in range(height):
                    brow=tmp[i]
                    arow=art2[i] if i < len(art2) else ""
                    res=[' ']*new_w
                    for j,chb in enumerate(brow):
                        if j<new_w:
                            res[j]=chb
                    start=cur_w-ov
                    for j,chn in enumerate(arow):
                        pos=start+j
                        if 0<=pos<new_w and chn!=' ':
                            res[pos]=chn
                    new_buf.append(''.join(res))
                tmp=new_buf
            else:
                ov=compute_overlap(tmp,char_rows)
                attempt=ov+1
                can=True
                infos=[]
                for i in range(height):
                    brow=tmp[i]
                    arow=char_rows[i] if i < len(char_rows) else ""
                    tb=trailing_blanks(brow)
                    lb=leading_blanks(arow)
                    if tb+lb==ov:
                        rb=-1
                        for idx in range(len(brow)-1,-1,-1):
                            if brow[idx]!=' ':
                                rb=idx
                                break
                        lb_idx=len(arow)
                        for idx,ch in enumerate(arow):
                            if ch!=' ':
                                lb_idx=idx
                                break
                        if rb==-1 or lb_idx==len(arow):
                            infos.append(None)
                            continue
                        c1=brow[rb]
                        c2=arow[lb_idx]
                        if layout=='SMUSH':
                            ok,rc=smush_pair(c1,c2,rules,hb)
                        else:
                            ok,rc=smush_old(c1,c2,hb)
                        if not ok:
                            can=False
                            break
                        infos.append((rb,lb_idx,rc))
                    else:
                        infos.append(None)
                if can:
                    new_w=cur_w + (max(len(r) for r in char_rows) if char_rows else 0) - attempt
                    new_buf=[]
                    for i in range(height):
                        brow=tmp[i]
                        arow=char_rows[i] if i < len(char_rows) else ""
                        res=[' ']*new_w
                        for j,chb in enumerate(brow):
                            if j<new_w:
                                res[j]=chb
                        start=cur_w-attempt
                        info=infos[i]
                        if info:
                            rb,lb_idx,rc=info
                            if rb<new_w:
                                res[rb]=rc
                            for j in range(lb_idx+1,len(arow)):
                                pos=start+j
                                if 0<=pos<new_w:
                                    chn=arow[j]
                                    if chn!=' ':
                                        res[pos]=chn
                        else:
                            for j,chn in enumerate(arow):
                                pos=start+j
                                if 0<=pos<new_w and chn!=' ':
                                    res[pos]=chn
                        new_buf.append(''.join(res))
                    tmp=new_buf
                else:
                    new_w=cur_w + (max(len(r) for r in char_rows) if char_rows else 0) - ov
                    new_buf=[]
                    for i in range(height):
                        brow=tmp[i]
                        arow=char_rows[i] if i < len(char_rows) else ""
                        res=[' ']*new_w
                        for j,chb in enumerate(brow):
                            if j<new_w:
                                res[j]=chb
                        start=cur_w-ov
                        for j,chn in enumerate(arow):
                            pos=start+j
                            if 0<=pos<new_w and chn!=' ':
                                res[pos]=chn
                        new_buf.append(''.join(res))
                    tmp=new_buf
        return tmp

    words=log_line.split()
    # If original line had leading/trailing spaces, split() loses them, but we earlier skip leading spaces anyway (original does not start line with spaces). So using split() is okay for wrapping?

    for word in words:
        # If cur_buf empty, we try to place word even if exceeds
        if all(b=="" for b in cur_buf):
            # Check if word itself exceeds width, then we need to break word char by char
            wb=render_word(word,font,layout,rules)
            ww=max(len(r) for r in wb) if wb else 0
            if ww <= width or width==80 and ww>width:
                # Actually even if exceeds, we still place it? But for words that exceed, we should break char by char
                if ww > width:
                    # break char by char
                    for ch in word:
                        # add char by char with wrapping
                        tentative=combine(cur_buf,ch)
                        tent_w=max(len(r) for r in tentative) if tentative else 0
                        if tent_w > width and not all(b=="" for b in cur_buf):
                            flush()
                            cur_buf=combine(["" for _ in range(height)],ch)
                        else:
                            cur_buf=tentative
                else:
                    cur_buf=wb
            else:
                cur_buf=wb
        else:
            # cur_buf not empty, we need to consider adding a space + word
            # First, compute width if we add space + word
            # For simplicity, we will try to add space then word as combined
            tentative_space=combine(cur_buf,' ')
            tentative_full=combine(tentative_space,word)
            tent_w=max(len(r) for r in tentative_full) if tentative_full else 0
            if tent_w > width:
                # Would exceed, flush current line, then start new line with word (which may itself need breaking)
                flush()
                wb=render_word(word,font,layout,rules)
                ww=max(len(r) for r in wb) if wb else 0
                if ww > width:
                    # break word char by char
                    cur_buf=["" for _ in range(height)]
                    for ch in word:
                        tentative=combine(cur_buf,ch)
                        tent_w2=max(len(r) for r in tentative) if tentative else 0
                        if tent_w2 > width and not all(b=="" for b in cur_buf):
                            flush()
                            cur_buf=combine(["" for _ in range(height)],ch)
                        else:
                            cur_buf=tentative
                else:
                    cur_buf=wb
            else:
                cur_buf=tentative_full

    if not all(b=="" for b in cur_buf):
        disp=[row.replace(hb,' ') for row in cur_buf]
        cur_w=max(len(r) for r in disp) if disp else 0
        lead=0
        if justify=='CENTER':
            lead=(width - cur_w)//2
        elif justify=='RIGHT':
            lead=width - cur_w
        elif justify=='LEFT':
            lead=0
        else:
            lead=width - cur_w if text_dir=='RIGHT' else 0
        if lead<0:
            lead=0
        for r in disp:
            final.append(' '*lead + r)
    return final

def main():
