                            elif ch=='C':
                                controls.append(val)
                            elif ch=='I':
                                try:
                                    infocode=int(val) if val is not None else 0
                                except:
                                    infocode=0
                            break
                        else:
                            if i+1 < len(args):
                                val=args[i+1]
                                i+=1
                                if ch=='d':
                                    fontdir=val
                                elif ch=='f':
                                    fontname=val
                                elif ch=='m':
                                    try:
                                        smush_mode=int(val) if val is not None else 0
                                    except:
                                        smush_mode=0
                                    if smush_mode==0:
                                        explicit_layout='KERN'
                                    elif smush_mode==-1:
                                        explicit_layout='FULL'
                                    elif smush_mode==-2:
