    i=0
    while i < len(token):
        if token[i:i+2]=="\\-":
            cps.append(ord('-'))
            i+=2
            continue
        cp,ni=parse_single(token,i)
        if cp is None:
            i+=1
            continue
        cps.append(cp)
        i=ni
