                        break
                if hexd:
                    try:
                        return int(hexd,16),j
                    except:
                        return ord('\\'),idx+1
                else:
                    return ord('\\'),idx+1
            if nxt.isdigit():
                j=idx+1
                num=""
                while j<len(s) and s[j].isdigit():
                    num+=s[j]
                    j+=1
                    if len(num)>=4:
                        break
                if num:
                    try:
