                        if j<new_w:
                            res[j]=chb
                    start=cur_w-attempt
                    info=infos[i]
                    if info:
                        rb,lb_idx,rc=info
                        if rb<new_w:
                            res[rb]=rc
                        for j in range(lb_idx+1,len(arow)):
                            pos=start+j
                            if 0<=pos<new_w:
                                chn=arow[j]
                                if chn!=' ':
                                    res[pos]=chn
                    else:
                        for j,chn in enumerate(arow):
                            pos=start+j
                            if 0<=pos<new_w and chn!=' ':
                                res[pos]=chn
                    new_buf.append(''.join(res))
                buf=new_buf
            else:
                new_w=cur_w + (max(len(r) for r in char_rows) if char_rows else 0) - ov
                new_buf=[]
                for i in range(height):
                    brow=buf[i]
                    arow=char_rows[i] if i < len(char_rows) else ""
                    res=[' ']*new_w
                    for j,chb in enumerate(brow):
                        if j<new_w:
                            res[j]=chb
                    start=cur_w-ov
                    for j,chn in enumerate(arow):
                        pos=start+j
                        if 0<=pos<new_w and chn!=' ':
                            res[pos]=chn
                    new_buf.append(''.join(res))
                buf=new_buf
    return buf

def render_logical_line(log_line,font,width,justify,text_dir,layout,rules):
    height=font['height']
    hb=font['hardblank']
    if width==1:
        out=[]
        for ch in log_line:
            if ch==' ':
                continue
            cp=ord(ch)
            art=font['cmap'].get(cp)
            if art is None:
                art=font['cmap'].get(32)
                if art is None:
                    art=[""]*height
            if layout!='FULL':
                art=trim_char(art,hb)
            disp=[row.replace(hb,' ') for row in art]
            out.extend(disp)
        return out
    if log_line=="":
        return ["" for _ in range(height)]
    words=log_line.split()
    final=[]
    cur_buf=["" for _ in range(height)]

    def flush():
        nonlocal cur_buf,final
        if not cur_buf or all(b=="" for b in cur_buf):
            return
        disp=[row.replace(hb,' ') for row in cur_buf]
        cur_w=max(len(r) for r in disp) if disp else 0
        lead=0
        if justify=='CENTER':
            lead=(width - cur_w)//2
        elif justify=='RIGHT':
            lead=width - cur_w -1
        elif justify=='LEFT':
            lead=0
        else:
            lead=width - cur_w -1 if text_dir=='RIGHT' else 0
        if lead<0:
            lead=0
        for r in disp:
            final.append(' '*lead + r)
        cur_buf=["" for _ in range(height)]

    def combine(buf,word):
        tmp=[row for row in buf]
        def get_art(cp):
            art=font['cmap'].get(cp)
            if art is None:
                art=font['cmap'].get(32)
                if art is None:
                    art=[""]*height
            return art if layout=='FULL' else trim_char(art,hb)
        for ch in word:
            cp=ord(ch)
            char_rows=get_art(cp)
            if not tmp or all(b=="" for b in tmp):
                tmp=[r for r in char_rows]
                continue
            cur_w=max(len(r) for r in tmp)
            if layout=='FULL':
                tmp=[tmp[i].ljust(cur_w)+(char_rows[i] if i < len(char_rows) else "") for i in range(height)]
            elif layout=='KERN':
                ov=compute_overlap(tmp,char_rows)
                new_w=cur_w + (max(len(r) for r in char_rows) if char_rows else 0) - ov
                new_buf=[]
                for i in range(height):
                    brow=tmp[i]
                    arow=char_rows[i] if i < len(char_rows) else ""
                    res=[' ']*new_w
                    for j,chb in enumerate(brow):
                        if j<new_w:
                            res[j]=chb
                    start=cur_w-ov
                    for j,chn in enumerate(arow):
                        pos=start+j
                        if 0<=pos<new_w and chn!=' ':
                            res[pos]=chn
                    new_buf.append(''.join(res))
                tmp=new_buf
            elif layout=='OVERLAP':
                ov=compute_overlap(tmp,char_rows)
                attempt=ov+1
                new_w=cur_w + (max(len(r) for r in char_rows) if char_rows else 0) - attempt
                new_buf=[]
                for i in range(height):
                    brow=tmp[i]
                    arow=char_rows[i] if i < len(char_rows) else ""
                    res=[' ']*new_w
                    for j,chb in enumerate(brow):
                        if j<new_w:
                            res[j]=chb
                    start=cur_w-attempt
                    for j,chn in enumerate(arow):
                        pos=start+j
                        if 0<=pos<new_w and chn!=' ':
                            res[pos]=chn
                    new_buf.append(''.join(res))
                tmp=new_buf
            else:
                ov=compute_overlap(tmp,char_rows)
                attempt=ov+1
                can=True
                infos=[]
                for i in range(height):
                    brow=tmp[i]
                    arow=char_rows[i] if i < len(char_rows) else ""
                    tb=trailing_blanks(brow)
                    lb=leading_blanks(arow)
                    if tb+lb==ov:
                        rb=-1
                        for idx in range(len(brow)-1,-1,-1):
                            if brow[idx]!=' ':
                                rb=idx
                                break
                        lb_idx=len(arow)
                        for idx,ch in enumerate(arow):
                            if ch!=' ':
                                lb_idx=idx
                                break
                        if rb==-1 or lb_idx==len(arow):
                            infos.append(None)
                            continue
                        c1=brow[rb]
                        c2=arow[lb_idx]
                        if layout=='SMUSH':
                            ok,rc=smush_pair(c1,c2,rules,hb)
                        else:
                            ok,rc=smush_old(c1,c2,hb)
                        if not ok:
                            can=False
                            break
                        infos.append((rb,lb_idx,rc))
                    else:
                        infos.append(None)
                if can:
                    new_w=cur_w + (max(len(r) for r in char_rows) if char_rows else 0) - attempt
                    new_buf=[]
                    for i in range(height):
                        brow=tmp[i]
                        arow=char_rows[i] if i < len(char_rows) else ""
                        res=[' ']*new_w
                        for j,chb in enumerate(brow):
                            if j<new_w:
                                res[j]=chb
                        start=cur_w-attempt
                        info=infos[i]
                        if info:
                            rb,lb_idx,rc=info
                            if rb<new_w:
                                res[rb]=rc
                            for j in range(lb_idx+1,len(arow)):
                                pos=start+j
                                if 0<=pos<new_w:
                                    chn=arow[j]
                                    if chn!=' ':
                                        res[pos]=chn
                        else:
                            for j,chn in enumerate(arow):
                                pos=start+j
                                if 0<=pos<new_w and chn!=' ':
                                    res[pos]=chn
                        new_buf.append(''.join(res))
                    tmp=new_buf
                else:
                    new_w=cur_w + (max(len(r) for r in char_rows) if char_rows else 0) - ov
                    new_buf=[]
                    for i in range(height):
                        brow=tmp[i]
                        arow=char_rows[i] if i < len(char_rows) else ""
                        res=[' ']*new_w
                        for j,chb in enumerate(brow):
                            if j<new_w:
                                res[j]=chb
                        start=cur_w-ov
                        for j,chn in enumerate(arow):
                            pos=start+j
                            if 0<=pos<new_w and chn!=' ':
                                res[pos]=chn
                        new_buf.append(''.join(res))
                    tmp=new_buf
        return tmp

    for word in words:
        if all(b=="" for b in cur_buf):
            wb=render_word(word,font,layout,rules)
            ww=max(len(r) for r in wb) if wb else 0
            if ww >= width:
                for ch in word:
                    tentative=combine(cur_buf,ch)
                    tent_w=max(len(r) for r in tentative) if tentative else 0
                    if tent_w >= width and not all(b=="" for b in cur_buf):
                        flush()
                        cur_buf=combine(["" for _ in range(height)],ch)
                    else:
                        cur_buf=tentative
            else:
                cur_buf=wb
        else:
            tentative_space=combine(cur_buf,' ')
            tentative_full=combine(tentative_space,word)
            tent_w=max(len(r) for r in tentative_full) if tentative_full else 0
            if tent_w >= width:
                flush()
                wb=render_word(word,font,layout,rules)
                ww=max(len(r) for r in wb) if wb else 0
                if ww >= width:
                    cur_buf=["" for _ in range(height)]
                    for ch in word:
                        tentative=combine(cur_buf,ch)
                        tent_w2=max(len(r) for r in tentative) if tentative else 0
                        if tent_w2 >= width and not all(b=="" for b in cur_buf):
                            flush()
                            cur_buf=combine(["" for _ in range(height)],ch)
                        else:
                            cur_buf=tentative
                else:
                    cur_buf=wb
            else:
                cur_buf=tentative_full

    if not all(b=="" for b in cur_buf):
        disp=[row.replace(hb,' ') for row in cur_buf]
        cur_w=max(len(r) for r in disp) if disp else 0
        lead=0
        if justify=='CENTER':
            lead=(width - cur_w)//2
        elif justify=='RIGHT':
            lead=width - cur_w -1
        elif justify=='LEFT':
            lead=0
        else:
            lead=width - cur_w -1 if text_dir=='RIGHT' else 0
        if lead<0:
            lead=0
        for r in disp:
            final.append(' '*lead + r)
    return final

def main():
    prog=os.path.basename(sys.argv[0])
    fontdir=None
    fontname=DEFAULT_FONT
    width=80
    smush_mode=None
    explicit_layout=None
    justify='X'
    text_dir='X'
    deutsch=False
    controls=[]
    infocode=None
    v_flag=False
    para_mode='NORMAL'
    valid_no_arg=set(list("cklnoprstvxDELNRSWX"))
    valid_arg=set(['d','f','m','w','C','I'])
    args=sys.argv[1:]
    i=0
    msg_parts=[]
    while i < len(args):
        arg=args[i]
        if arg=='--':
            msg_parts.extend(args[i+1:])
            break
        if arg.startswith('-') and len(arg)>1 and arg!="-":
            if arg[1] in valid_arg:
                flag=arg[1]
                val=arg[2:] if len(arg)>2 else (args[i+1] if i+1 < len(args) else None)
                if len(arg)==2 and val is not None:
                    i+=1
                if flag=='d':
                    fontdir=val
                elif flag=='f':
                    fontname=val
                elif flag=='m':
                    try:
                        smush_mode=int(val) if val is not None else 0
                    except:
                        smush_mode=0
                    if smush_mode==0:
                        explicit_layout='KERN'
                    elif smush_mode==-1:
                        explicit_layout='FULL'
                    elif smush_mode==-2:
                        explicit_layout='SMUSH'
                    else:
                        explicit_layout='SMUSH'
                        if (smush_mode & 63)==0 and smush_mode!=0:
                            smush_mode=63
                        else:
                            if smush_mode>0:
                                smush_mode=smush_mode & 63
                                if smush_mode==0:
                                    smush_mode=63
                            else:
                                smush_mode=abs(smush_mode) & 63
                                if smush_mode==0:
                                    smush_mode=63
                elif flag=='w':
                    try:
                        w=int(val) if val is not None else 80
                    except:
                        w=80
                    if w!=0:
                        width=w
                elif flag=='C':
                    controls.append(val)
                elif flag=='I':
                    try:
                        infocode=int(val) if val is not None else 0
                    except:
                        infocode=0
            else:
                pos=1
                while pos < len(arg):
                    ch=arg[pos]
                    if ch in valid_arg:
                        if pos+1 < len(arg):
                            val=arg[pos+1:]
                            if ch=='d':
                                fontdir=val
                            elif ch=='f':
                                fontname=val
                            elif ch=='m':
                                try:
                                    smush_mode=int(val) if val is not None else 0
                                except:
                                    smush_mode=0
                                if smush_mode==0:
                                    explicit_layout='KERN'
                                elif smush_mode==-1:
                                    explicit_layout='FULL'
                                elif smush_mode==-2:
                                    explicit_layout='SMUSH'
                                else:
                                    explicit_layout='SMUSH'
                                    if (smush_mode & 63)==0 and smush_mode!=0:
                                        smush_mode=63
                                    else:
                                        if smush_mode>0:
                                            smush_mode=smush_mode & 63
                                            if smush_mode==0:
                                                smush_mode=63
                                        else:
                                            smush_mode=abs(smush_mode) & 63
                                            if smush_mode==0:
                                                smush_mode=63
                            elif ch=='w':
                                try:
                                    w=int(val) if val is not None else 80
                                except:
                                    w=80
                                if w!=0:
                                    width=w
                            elif ch=='C':
                                controls.append(val)
                            elif ch=='I':
                                try:
                                    infocode=int(val) if val is not None else 0
                                except:
                                    infocode=0
                            break
                        else:
                            if i+1 < len(args):
                                val=args[i+1]
                                i+=1
                                if ch=='d':
                                    fontdir=val
                                elif ch=='f':
                                    fontname=val
                                elif ch=='m':
                                    try:
                                        smush_mode=int(val) if val is not None else 0
                                    except:
                                        smush_mode=0
                                    if smush_mode==0:
                                        explicit_layout='KERN'
                                    elif smush_mode==-1:
                                        explicit_layout='FULL'
                                    elif smush_mode==-2:
                                        explicit_layout='SMUSH'
                                    else:
                                        explicit_layout='SMUSH'
                                        if (smush_mode & 63)==0 and smush_mode!=0:
                                            smush_mode=63
                                        else:
                                            if smush_mode>0:
                                                smush_mode=smush_mode & 63
                                                if smush_mode==0:
                                                    smush_mode=63
                                            else:
                                                smush_mode=abs(smush_mode) & 63
                                                if smush_mode==0:
                                                    smush_mode=63
                                elif ch=='w':
                                    try:
                                        w=int(val) if val is not None else 80
                                    except:
                                        w=80
                                    if w!=0:
                                        width=w
                                elif ch=='C':
                                    controls.append(val)
                                elif ch=='I':
                                    try:
                                        infocode=int(val) if val is not None else 0
                                    except:
                                        infocode=0
                                break
                            else:
                                break
                    else:
                        if ch not in valid_no_arg:
                            if ch=='F':
                                sys.stderr.write(f"{prog}: illegal option -- {ch}\n")
                                print_usage(prog, sys.stderr)
                                sys.stderr.write("\nBecause of numerous incompatibilities, the \"-F\" option has been\n")
                                sys.stderr.write("removed.  It has been replaced by the \"figlist\" program, which is now\n")
                                sys.stderr.write("included in the basic FIGlet package.  \"figlist\" is also available\n")
                                sys.stderr.write("from  http://www.figlet.org/under UNIX utilities.\n")
                                sys.exit(1)
                            else:
                                sys.stderr.write(f"{prog}: invalid option -- '{ch}'\n")
                                print_usage(prog, sys.stderr)
                                sys.exit(1)
                        else:
                            if ch=='c':
                                justify='CENTER'
                            elif ch=='l':
                                justify='LEFT'
                            elif ch=='r':
                                justify='RIGHT'
                            elif ch=='x':
                                justify='X'
                            elif ch=='k':
                                explicit_layout='KERN'
                            elif ch=='W':
                                explicit_layout='FULL'
                            elif ch=='o':
                                explicit_layout='OVERLAP'
                            elif ch=='s':
                                explicit_layout='SMUSH'
                            elif ch=='S':
                                explicit_layout='SMUSH_OLD'
                            elif ch=='n':
                                para_mode='NORMAL'
                            elif ch=='p':
                                para_mode='PARA'
                            elif ch=='t':
                                try:
                                    cols=shutil.get_terminal_size().columns
                                    if cols>0:
                                        width=cols
                                except:
                                    pass
                            elif ch=='v':
                                v_flag=True
                            elif ch=='D':
                                deutsch=True
                            elif ch=='E':
                                deutsch=False
                            elif ch=='L':
                                text_dir='LEFT'
                            elif ch=='R':
                                text_dir='RIGHT'
                            elif ch=='X':
                                text_dir='X'
                            elif ch=='N':
                                controls=[]
                        pos+=1
        else:
            msg_parts.append(arg)
        i+=1

    if v_flag:
        infocode=0
    if infocode is not None:
        if infocode==0:
            print_version(prog, sys.stdout)
            sys.exit(0)
        elif infocode==1:
            sys.stdout.write(f"{VERSION_NUM}\n")
            sys.exit(0)
        elif infocode==2:
            if fontdir:
                sys.stdout.write(f"{fontdir}\n")
            else:
                env_dir=os.environ.get('FIGLET_FONTDIR')
                if env_dir:
                    sys.stdout.write(f"{env_dir}\n")
                else:
                    sys.stdout.write(f"./fonts\n" if os.path.isdir("./fonts") else f"/usr/local/share/figlet\n")
            sys.exit(0)
        elif infocode==3:
            fn=os.path.basename(fontname)
            if fn.lower().endswith('.flf'):
                fn=fn[:-4]
            elif fn.lower().endswith('.tlf'):
                fn=fn[:-4]
            sys.stdout.write(f"{fn}\n")
            sys.exit(0)
        elif infocode==4:
            sys.stdout.write(f"{width}\n")
            sys.exit(0)
        elif infocode==5:
            sys.stdout.write(f"{SUPPORTED_FORMATS}\n")
            sys.exit(0)
        else:
            sys.exit(0)

    font_path=find_font_file(fontname, fontdir)
    if not font_path:
        sys.stderr.write(f"{prog}: {fontname}: Unable to open font file\n")
        sys.exit(1)
    font_data,err=load_font_file(font_path)
    if err=="notfound":
        sys.stderr.write(f"{prog}: {fontname}: Unable to open font file\n")
        sys.exit(1)
    elif err=="bad":
        sys.stderr.write(f"{prog}: {font_path}: Not a FIGlet 2 font file\n")
        sys.exit(1)

    default_layout,default_rules=get_default_layout(font_data)
    if explicit_layout is None:
        layout_type=default_layout
        smush_rules=default_rules
    else:
        if explicit_layout=='SMUSH':
            if smush_mode is None:
                if default_layout=='SMUSH':
                    layout_type='SMUSH'
                    smush_rules=default_rules
                else:
                    layout_type=default_layout
                    smush_rules=default_rules
            else:
                layout_type='SMUSH'
                smush_rules=smush_mode
        elif explicit_layout=='KERN':
            layout_type='KERN'
            smush_rules=0
        elif explicit_layout=='FULL':
            layout_type='FULL'
            smush_rules=0
        elif explicit_layout=='OVERLAP':
            layout_type='OVERLAP'
            smush_rules=0
        elif explicit_layout=='SMUSH_OLD':
            layout_type='SMUSH_OLD'
            smush_rules=default_rules
        else:
            layout_type=explicit_layout
            smush_rules=smush_mode if smush_mode is not None else 0

    if text_dir=='X':
        effective_dir='RIGHT' if font_data['print_dir']==1 else 'LEFT'
    elif text_dir=='LEFT':
        effective_dir='LEFT'
    else:
        effective_dir='RIGHT'

    effective_justify=justify
    if justify=='X':
        effective_justify='RIGHT' if effective_dir=='RIGHT' else 'LEFT'

    combined_trans={}
    formatA_maps=[]
    for ctrlname in controls:
        ctrl_path=find_control_file(ctrlname, fontdir)
        if not ctrl_path:
            sys.stderr.write(f"{prog}: {ctrlname}: Unable to open control file\n")
            sys.exit(1)
        ctrl_data,err=load_control_file_simple(ctrl_path)
        if err=="notfound":
            sys.stderr.write(f"{prog}: {ctrlname}: Unable to open control file\n")
            sys.exit(1)
        if ctrl_data:
            if ctrl_data.get('formatA'):
                formatA_maps.append(ctrl_data['translations'])
            else:
                for k,v in ctrl_data['translations'].items():
                    combined_trans[k]=v

    if msg_parts:
        logical=[]
        cur=""
        i=0
        while i < len(msg_parts):
            part=msg_parts[i]
            if part=="":
                if cur!="":
                    logical.append(cur)
                    cur=""
                else:
                    j=i
                    while j < len(msg_parts) and msg_parts[j]=="":
                        j+=1
                    n=j-i
                    has_future=any(x!="" for x in msg_parts[j:])
                    if has_future:
                        for _ in range(n):
                            logical.append("")
                    else:
                        for _ in range(max(0,n-1)):
                            logical.append("")
                    i=j-1
            else:
                if cur=="":
                    cur=part
                else:
                    cur=cur+" "+part
            i+=1
        if cur!="":
            logical.append(cur)
        if logical and logical[-1]=="":
            logical.pop()
        input_text="\n".join(logical)
    else:
        data=sys.stdin.read()
        data=data.replace('\r','\n').replace('\x0b','\n').replace('\x0c','\n').replace('\t',' ')
        if para_mode=='PARA':
            res=[]
            for idx,ch in enumerate(data):
                if ch=='\n':
                    prev=data[idx-1] if idx>0 else '\n'
                    nxt=data[idx+1] if idx+1 < len(data) else '\n'
                    if prev!='\n' and nxt not in (' ','\n'):
                        res.append(' ')
                    else:
                        res.append('\n')
                else:
                    res.append(ch)
            data=''.join(res)
        input_text=data

    if deutsch:
        trans={ord('['):196, ord('\\'):214, ord(']'):220, ord('{'):228, ord('|'):246, ord('}'):252, ord('~'):223}
        input_text=''.join(chr(trans[ord(ch)]) if ord(ch) in trans else ch for ch in input_text)

    if combined_trans:
        input_text=''.join(chr(combined_trans[ord(ch)]) if ord(ch) in combined_trans else ch for ch in input_text)

    if formatA_maps:
        combinedA={}
        for m in formatA_maps:
            for k,v in m.items():
                combinedA[k]=v
        input_text=''.join(chr(combinedA[ord(ch)]) if ord(ch) in combinedA else ch for ch in input_text)

    logical_lines=input_text.split('\n')
    if effective_dir=='RIGHT':
        logical_lines=[line[::-1] for line in logical_lines]

    all_out=[]
    for log_line in logical_lines:
        rendered=render_logical_line(log_line, font_data, width, effective_justify, effective_dir, layout_type, smush_rules if 'smush_rules' in locals() else 0)
        all_out.extend(rendered)

    for line in all_out:
        sys.stdout.write(line + "\n")

if __name__=="__main__":
    main()
