                    brow=buf[i]
                    arow=char_rows[i] if i < len(char_rows) else ""
                    res=[' ']*new_w
                    for j,chb in enumerate(brow):
                        if j<new_w:
                            res[j]=chb
                    start=cur_w-attempt
                    info=infos[i]
                    if info:
                        rb,lb_idx,rc=info
                        if rb<new_w:
                            res[rb]=rc
                        for j in range(lb_idx+1,len(arow)):
                            pos=start+j
                            if 0<=pos<new_w:
                                chn=arow[j]
                                if chn!=' ':
                                    res[pos]=chn
                    else:
                        for j,chn in enumerate(arow):
                            pos=start+j
                            if 0<=pos<new_w and chn!=' ':
                                res[pos]=chn
                    new_buf.append(''.join(res))
                buf=new_buf
            else:
                new_w=cur_w + (max(len(r) for r in char_rows) if char_rows else 0) - ov
                new_buf=[]
                for i in range(height):
                    brow=buf[i]
                    arow=char_rows[i] if i < len(char_rows) else ""
                    res=[' ']*new_w
                    for j,chb in enumerate(brow):
                        if j<new_w:
                            res[j]=chb
                    start=cur_w-ov
                    for j,chn in enumerate(arow):
                        pos=start+j
                        if 0<=pos<new_w and chn!=' ':
                            res[pos]=chn
                    new_buf.append(''.join(res))
                buf=new_buf
    return buf

def render_logical_line(log_line,font,width,justify,text_dir,layout,rules):
    height=font['height']
    hb=font['hardblank']
    if width==1:
        out=[]
        for ch in log_line:
            if ch==' ':
                continue
            cp=ord(ch)
            art=font['cmap'].get(cp)
            if art is None:
                art=font['cmap'].get(32)
                if art is None:
                    art=[""]*height
            disp=[row.replace(hb,' ') for row in art]
            out.extend(disp)
        return out
    if log_line=="":
        return ["" for _ in range(height)]
    # check if all spaces
    if log_line.strip()=="" :
        # all spaces -> render spaces
        # count spaces
        n=len(log_line)
        # For each space, we need its art? Space art width is? We'll render n spaces as word of spaces
        # Use render_word for n spaces
        buf=render_word(log_line, font, layout, rules)
        disp=[row.replace(hb,' ') for row in buf]
        # For justification, compute width etc.
        cur_w=max(len(r) for r in disp) if disp else 0
        lead=0
        if justify=='CENTER':
            lead=(width - cur_w)//2
        elif justify=='RIGHT':
            lead=width - cur_w -1
        elif justify=='LEFT':
            lead=0
        else:
            lead=width - cur_w -1 if text_dir=='RIGHT' else 0
        if lead<0:
            lead=0
        return [' '*lead + r for r in disp]

    words=log_line.split()
    final=[]
    cur_buf=["" for _ in range(height)]

    def flush():
        nonlocal cur_buf,final
        if not cur_buf or all(b=="" for b in cur_buf):
            return
        disp=[row.replace(hb,' ') for row in cur_buf]
        cur_w=max(len(r) for r in disp) if disp else 0
        lead=0
        if justify=='CENTER':
            lead=(width - cur_w)//2
        elif justify=='RIGHT':
            lead=width - cur_w -1
        elif justify=='LEFT':
            lead=0
        else:
            lead=width - cur_w -1 if text_dir=='RIGHT' else 0
        if lead<0:
            lead=0
        for r in disp:
            final.append(' '*lead + r)
        cur_buf=["" for _ in range(height)]

    def combine(buf,word):
        tmp=[row for row in buf]
        def get_art(cp):
            art=font['cmap'].get(cp)
            if art is None:
                art=font['cmap'].get(32)
                if art is None:
                    art=[""]*height
            return art if layout=='FULL' else trim_char(art,hb)
        for ch in word:
            cp=ord(ch)
            char_rows=get_art(cp)
            if not tmp or all(b=="" for b in tmp):
                tmp=[r for r in char_rows]
                continue
            cur_w=max(len(r) for r in tmp)
            if layout=='FULL':
                tmp=[tmp[i].ljust(cur_w)+(char_rows[i] if i < len(char_rows) else "") for i in range(height)]
            elif layout=='KERN':
                ov=compute_overlap(tmp,char_rows)
                new_w=cur_w + (max(len(r) for r in char_rows) if char_rows else 0) - ov
                new_buf=[]
                for i in range(height):
                    brow=tmp[i]
                    arow=char_rows[i] if i < len(char_rows) else ""
                    res=[' ']*new_w
                    for j,chb in enumerate(brow):
                        if j<new_w:
                            res[j]=chb
                    start=cur_w-ov
                    for j,chn in enumerate(arow):
                        pos=start+j
                        if 0<=pos<new_w and chn!=' ':
                            res[pos]=chn
                    new_buf.append(''.join(res))
                tmp=new_buf
            elif layout=='OVERLAP':
                ov=compute_overlap(tmp,char_rows)
                attempt=ov+1
                new_w=cur_w + (max(len(r) for r in char_rows) if char_rows else 0) - attempt
                new_buf=[]
                for i in range(height):
                    brow=tmp[i]
                    arow=char_rows[i] if i < len(char_rows) else ""
                    res=[' ']*new_w
                    for j,chb in enumerate(brow):
                        if j<new_w:
                            res[j]=chb
                    start=cur_w-attempt
                    for j,chn in enumerate(arow):
                        pos=start+j
                        if 0<=pos<new_w and chn!=' ':
                            res[pos]=chn
                    new_buf.append(''.join(res))
                tmp=new_buf
            else:
                ov=compute_overlap(tmp,char_rows)
                attempt=ov+1
                can=True
                infos=[]
                for i in range(height):
                    brow=tmp[i]
                    arow=char_rows[i] if i < len(char_rows) else ""
                    tb=trailing_blanks(brow)
                    lb=leading_blanks(arow)
                    if tb+lb==ov:
                        rb=-1
                        for idx in range(len(brow)-1,-1,-1):
                            if brow[idx]!=' ':
                                rb=idx
                                break
                        lb_idx=len(arow)
                        for idx,ch in enumerate(arow):
                            if ch!=' ':
                                lb_idx=idx
                                break
                        if rb==-1 or lb_idx==len(arow):
                            infos.append(None)
                            continue
                        c1=brow[rb]
                        c2=arow[lb_idx]
                        if layout=='SMUSH':
                            ok,rc=smush_pair(c1,c2,rules,hb)
                        else:
                            ok,rc=smush_old(c1,c2,hb)
                        if not ok:
                            can=False
                            break
                        infos.append((rb,lb_idx,rc))
                    else:
                        infos.append(None)
                if can:
                    new_w=cur_w + (max(len(r) for r in char_rows) if char_rows else 0) - attempt
                    new_buf=[]
                    for i in range(height):
                        brow=tmp[i]
                        arow=char_rows[i] if i < len(char_rows) else ""
                        res=[' ']*new_w
                        for j,chb in enumerate(brow):
                            if j<new_w:
                                res[j]=chb
                        start=cur_w-attempt
                        info=infos[i]
                        if info:
                            rb,lb_idx,rc=info
                            if rb<new_w:
                                res[rb]=rc
                            for j in range(lb_idx+1,len(arow)):
                                pos=start+j
                                if 0<=pos<new_w:
                                    chn=arow[j]
                                    if chn!=' ':
                                        res[pos]=chn
                        else:
                            for j,chn in enumerate(arow):
                                pos=start+j
                                if 0<=pos<new_w and chn!=' ':
                                    res[pos]=chn
                        new_buf.append(''.join(res))
                    tmp=new_buf
                else:
                    new_w=cur_w + (max(len(r) for r in char_rows) if char_rows else 0) - ov
                    new_buf=[]
                    for i in range(height):
                        brow=tmp[i]
                        arow=char_rows[i] if i < len(char_rows) else ""
                        res=[' ']*new_w
                        for j,chb in enumerate(brow):
                            if j<new_w:
                                res[j]=chb
                        start=cur_w-ov
                        for j,chn in enumerate(arow):
                            pos=start+j
                            if 0<=pos<new_w and chn!=' ':
                                res[pos]=chn
                        new_buf.append(''.join(res))
                    tmp=new_buf
        return tmp

    for word in words:
        if all(b=="" for b in cur_buf):
            wb=render_word(word,font,layout,rules)
            ww=max(len(r) for r in wb) if wb else 0
            if ww >= width:
                for ch in word:
                    tentative=combine(cur_buf,ch)
                    tent_w=max(len(r) for r in tentative) if tentative else 0
                    if tent_w >= width and not all(b=="" for b in cur_buf):
                        flush()
                        cur_buf=combine(["" for _ in range(height)],ch)
                    else:
                        cur_buf=tentative
            else:
                cur_buf=wb
        else:
            tentative_space=combine(cur_buf,' ')
            tentative_full=combine(tentative_space,word)
            tent_w=max(len(r) for r in tentative_full) if tentative_full else 0
            if tent_w >= width:
                flush()
                wb=render_word(word,font,layout,rules)
                ww=max(len(r) for r in wb) if wb else 0
                if ww >= width:
                    cur_buf=["" for _ in range(height)]
                    for ch in word:
                        tentative=combine(cur_buf,ch)
                        tent_w2=max(len(r) for r in tentative) if tentative else 0
                        if tent_w2 >= width and not all(b=="" for b in cur_buf):
                            flush()
                            cur_buf=combine(["" for _ in range(height)],ch)
                        else:
                            cur_buf=tentative
                else:
                    cur_buf=wb
            else:
                cur_buf=tentative_full

    if not all(b=="" for b in cur_buf):
        disp=[row.replace(hb,' ') for row in cur_buf]
        cur_w=max(len(r) for r in disp) if disp else 0
        lead=0
        if justify=='CENTER':
            lead=(width - cur_w)//2
        elif justify=='RIGHT':
            lead=width - cur_w -1
        elif justify=='LEFT':
            lead=0
        else:
            lead=width - cur_w -1 if text_dir=='RIGHT' else 0
        if lead<0:
            lead=0
        for r in disp:
            final.append(' '*lead + r)
    return final

