                    arow=char_rows[i] if i < len(char_rows) else ""
                    res=[' ']*new_w
                    for j,chb in enumerate(brow):
                        if j<new_w:
                            res[j]=chb
                    start=cur_w-attempt
                    info=infos[i]
                    if info:
                        rb,lb_idx,rc=info
