                elif flag=='I':
                    try:
                        infocode=int(val) if val is not None else 0
                    except:
                        infocode=0
            else:
                pos=1
                while pos < len(arg):
                    ch=arg[pos]
                    if ch in valid_arg:
                        if pos+1 < len(arg):
                            val=arg[pos+1:]
                            if ch=='d':
                                fontdir=val
                            elif ch=='f':
                                fontname=val
                            elif ch=='m':
                                try:
                                    smush_mode=int(val) if val is not None else 0
