                                elif smush_mode==-1:
                                    explicit_layout='FULL'
                                    smush_mode=None
                                elif smush_mode==-2:
                                    explicit_layout='SMUSH'
                                    smush_mode=None
                                else:
                                    explicit_layout='SMUSH'
                                    if (smush_mode & 63)==0 and smush_mode!=0:
                                        smush_mode=63
                                    else:
                                        if smush_mode>0:
                                            smush_mode=smush_mode & 63
                                            if smush_mode==0:
                                                smush_mode=63
                                        else:
                                            smush_mode=abs(smush_mode) & 63
                                            if smush_mode==0:
                                                smush_mode=63
                            elif ch=='w':
                                try:
                                    w=int(val) if val is not None else 80
                                except:
                                    w=80
                                if w!=0:
                                    width=w
                            elif ch=='C':
                                controls.append(val)
                            elif ch=='I':
                                try:
                                    infocode=int(val) if val is not None else 0
                                except:
                                    infocode=0
                            break
                        else:
                            if i+1 < len(args):
                                val=args[i+1]
                                i+=1
                                if ch=='d':
                                    fontdir=val
                                elif ch=='f':
                                    fontname=val
                                elif ch=='m':
                                    try:
                                        smush_mode=int(val) if val is not None else 0
                                    except:
                                        smush_mode=0
                                    if smush_mode==0:
                                        explicit_layout='KERN'
                                        smush_mode=None
                                    elif smush_mode==-1:
                                        explicit_layout='FULL'
                                        smush_mode=None
                                    elif smush_mode==-2:
                                        explicit_layout='SMUSH'
                                        smush_mode=None
                                    else:
                                        explicit_layout='SMUSH'
                                        if (smush_mode & 63)==0 and smush_mode!=0:
                                            smush_mode=63
                                        else:
                                            if smush_mode>0:
                                                smush_mode=smush_mode & 63
