        if para_mode=='PARA':
            res=[]
            for idx,ch in enumerate(data):
                if ch=='\n':
                    prev=data[idx-1] if idx>0 else '\n'
                    nxt=data[idx+1] if idx+1 < len(data) else '\n'
                    if prev!='\n' and nxt not in (' ','\n'):
                        res.append(' ')
                    else:
                        res.append('\n')
                else:
                    res.append(ch)
            data=''.join(res)
        input_text=data

    if deutsch:
        trans={ord('['):196, ord('\\'):214, ord(']'):220, ord('{'):228, ord('|'):246, ord('}'):252, ord('~'):223}
        input_text=''.join(chr(trans[ord(ch)]) if ord(ch) in trans else ch for ch in input_text)

    if combined_trans:
        input_text=''.join(chr(combined_trans[ord(ch)]) if ord(ch) in combined_trans else ch for ch in input_text)

    if formatA_maps:
        combinedA={}
        for m in formatA_maps:
            for k,v in m.items():
                combinedA[k]=v
        input_text=''.join(chr(combinedA[ord(ch)]) if ord(ch) in combinedA else ch for ch in input_text)

    logical_lines=input_text.split('\n')
    if effective_dir=='RIGHT':
        logical_lines=[line[::-1] for line in logical_lines]

    all_out=[]
    for log_line in logical_lines:
        rendered=render_logical_line(log_line, font_data, width, effective_justify, effective_dir, layout_type, smush_rules if 'smush_rules' in locals() else 0)
        all_out.extend(rendered)

    for line in all_out:
        sys.stdout.write(line + "\n")

