                    except:
                        return ord('\\'),idx+1
                else:
                    return ord('\\'),idx+1
            if nxt.isdigit():
                j=idx+1
                num=""
                while j<len(s) and s[j].isdigit():
                    num+=s[j]
                    j+=1
                    if len(num)>=4:
                        break
                if num:
                    try:
                        return int(num),j
                    except:
                        return ord(nxt),idx+1
                else:
                    return ord(nxt),idx+2
            else:
                return ord(nxt),idx+2
