        i=ni
    return cps

def load_control_file_simple(filepath):
    if not os.path.isfile(filepath):
        return None,"notfound"
    try:
        with open(filepath,'rb') as f:
            data=f.read().decode('utf-8',errors='replace')
    except:
        data=""
    lines=data.splitlines()
    trans={}
    flags={'utf8':False}
    if not lines:
        return {'translations':trans,'flags':flags,'formatA':False},None
    first=lines[0].strip()
    if first=="flc2a":
        for line in lines[1:]:
            stripped=line.strip()
            if not stripped or stripped.startswith('#'):
                continue
            cmd=stripped[0]
            if cmd=='t':
                rest=stripped[1:].strip()
                parts=rest.split()
                if len(parts)<2:
                    continue
                from_cps=expand_control_token(parts[0])
                to_cps=expand_control_token(parts[1])
                if not from_cps or not to_cps:
                    continue
                if len(to_cps)==1:
                    for fc in from_cps:
                        trans[fc]=to_cps[0]
                else:
                    for idx,fc in enumerate(from_cps):
                        trans[fc]=to_cps[idx] if idx < len(to_cps) else to_cps[-1]
            elif cmd=='u':
                flags['utf8']=True
            else:
                parts=stripped.split()
                if len(parts)>=2:
                    try:
                        from_cps=expand_control_token(parts[0])
                        to_cps=expand_control_token(parts[1])
                        if from_cps and to_cps:
                            if len(to_cps)==1:
                                for fc in from_cps:
                                    trans[fc]=to_cps[0]
                            else:
                                for idx,fc in enumerate(from_cps):
                                    trans[fc]=to_cps[idx] if idx < len(to_cps) else to_cps[-1]
                    except:
                        pass
        return {'translations':trans,'flags':flags,'formatA':False},None
    else:
        for line in lines:
            stripped=line.strip()
            if not stripped or stripped.startswith('#'):
                continue
            m=re.match(r'0x([0-9A-Fa-f]+)\s+0x([0-9A-Fa-f]+)',stripped)
            if m:
                try:
                    src=int(m.group(1),16)
                    dst=int(m.group(2),16)
                    trans[src]=dst
                except:
                    continue
        return {'translations':trans,'flags':flags,'formatA':True},None

def trim_char(art,hb):
    lefts=[]
    rights=[]
    for row in art:
        lm=len(row)
        for idx,ch in enumerate(row):
            if ch!=' ':
                lm=idx
                break
        lefts.append(lm)
        rm=-1
        for idx in range(len(row)-1,-1,-1):
            if row[idx]!=' ':
                rm=idx
                break
        rights.append(rm)
    cl=min(lefts) if lefts else 0
    trail=[]
    for row,rm in zip(art,rights):
        if rm==-1:
            trail.append(len(row))
        else:
            trail.append(len(row)-1-rm)
    ct=min(trail) if trail else 0
    res=[]
    for row in art:
        end=len(row)-ct if ct>0 else len(row)
        start=cl
        if start>len(row):
            res.append("")
        else:
            res.append(row[start:end] if start<=end else "")
    return res

def leading_blanks(row):
    for i,ch in enumerate(row):
        if ch!=' ':
            return i
    return len(row)
def trailing_blanks(row):
    for i in range(len(row)-1,-1,-1):
        if row[i]!=' ':
            return len(row)-1-i
    return len(row)

def smush_pair(c1,c2,rules,hb):
    if c1==' ':
        return True,c2
    if c2==' ':
        return True,c1
    if c1==hb and c2==hb:
        return (True,hb) if (rules & SM_HARDBLANK) else (False,None)
    if c1==hb or c2==hb:
        return False,None
    if c1==c2:
        return (True,c1) if (rules & SM_EQUAL) else (False,None)
    if rules & SM_LOWLINE:
        if c1=='_':
            if c2 in "|/\\[]{}()<>":
                return True,c2
        if c2=='_':
            if c1 in "|/\\[]{}()<>":
                return True,c1
    if rules & SM_HIERARCHY:
        if c1 in _hierarchy and c2 in _hierarchy and _hierarchy[c1]!=_hierarchy[c2]:
            return True, c1 if _hierarchy[c1]>_hierarchy[c2] else c2
    if rules & SM_PAIR:
        if (c1=='[' and c2==']') or (c1==']' and c2=='[') or (c1=='{' and c2=='}') or (c1=='}' and c2=='{') or (c1=='(' and c2==')') or (c1==')' and c2=='(') or (c1=='<' and c2=='>') or (c1=='>' and c2=='<'):
            return True,'|'
    if rules & SM_BIGX:
        if (c1=='/' and c2=='\\') or (c1=='\\' and c2=='/'):
            return True,'|'
        if (c1=='<' and c2=='>') or (c1=='>' and c2=='<'):
            return True,'X'
    return False,None

def smush_old(c1,c2,hb):
    if c1==' ':
        return True,c2
    if c2==' ':
        return True,c1
    if c1==hb and c2==hb:
        return True,hb
    if c1==hb or c2==hb:
        return False,None
    if c1==c2:
        return True,c1
    if c1=='_':
        if c2 in "|/\\[]{}()<>":
            return True,c2
    if c2=='_':
        if c1 in "|/\\[]{}()<>":
            return True,c1
    if c1 in _hierarchy and c2 in _hierarchy and _hierarchy[c1]!=_hierarchy[c2]:
        return True, c1 if _hierarchy[c1]>_hierarchy[c2] else c2
    if (c1=='[' and c2==']') or (c1==']' and c2=='[') or (c1=='{' and c2=='}') or (c1=='}' and c2=='{') or (c1=='(' and c2==')') or (c1==')' and c2=='(') or (c1=='<' and c2=='>') or (c1=='>' and c2=='<'):
        return True,'|'
    if (c1=='/' and c2=='\\') or (c1=='\\' and c2=='/'):
        return True,'|'
    if (c1=='<' and c2=='>') or (c1=='>' and c2=='<'):
        return True,'X'
    return True,c2

def get_default_layout(font):
    full=font['full_layout']
    old=font['old_layout']
    if full!=0:
        low=full & 0xFF
        if low & 128:
            return 'SMUSH', low & 63
        elif low & 64:
            return 'KERN',0
        else:
            if low & 63:
                return 'SMUSH', low & 63
            return 'FULL',0
    if old==-1:
        return 'FULL',0
    elif old==0:
        return 'KERN',0
    elif old>0:
        return 'SMUSH',old
    else:
        return 'FULL',0

def compute_overlap(buf,new):
    m=None
    for b,n in zip(buf,new):
        tot=trailing_blanks(b)+leading_blanks(n)
        if m is None or tot<m:
            m=tot
    return 0 if m is None else m

def render_word(word,font,layout,rules):
    height=font['height']
    def get_art(cp):
        art=font['cmap'].get(cp)
        if art is None:
            art=font['cmap'].get(32)
            if art is None:
                art=[""]*height
        return art if layout=='FULL' else trim_char(art,font['hardblank'])
    buf=["" for _ in range(height)]
    first=True
    for ch in word:
        cp=ord(ch)
        char_rows=get_art(cp)
        if first:
            buf=[r for r in char_rows]
            first=False
            continue
        cur_w=max(len(r) for r in buf)
        if layout=='FULL':
            buf=[buf[i].ljust(cur_w)+(char_rows[i] if i < len(char_rows) else "") for i in range(height)]
        elif layout=='KERN':
            ov=compute_overlap(buf,char_rows)
            new_w=cur_w + (max(len(r) for r in char_rows) if char_rows else 0) - ov
            new_buf=[]
            for i in range(height):
                brow=buf[i]
                arow=char_rows[i] if i < len(char_rows) else ""
                res=[' ']*new_w
                for j,chb in enumerate(brow):
                    if j<new_w:
                        res[j]=chb
                start=cur_w-ov
                for j,chn in enumerate(arow):
                    pos=start+j
                    if 0<=pos<new_w and chn!=' ':
                        res[pos]=chn
                new_buf.append(''.join(res))
            buf=new_buf
        elif layout=='OVERLAP':
            ov=compute_overlap(buf,char_rows)
            attempt=ov+1
            new_w=cur_w + (max(len(r) for r in char_rows) if char_rows else 0) - attempt
            new_buf=[]
            for i in range(height):
                brow=buf[i]
                arow=char_rows[i] if i < len(char_rows) else ""
                res=[' ']*new_w
                for j,chb in enumerate(brow):
                    if j<new_w:
                        res[j]=chb
                start=cur_w-attempt
                for j,chn in enumerate(arow):
                    pos=start+j
                    if 0<=pos<new_w and chn!=' ':
                        res[pos]=chn
                new_buf.append(''.join(res))
            buf=new_buf
        else:
            ov=compute_overlap(buf,char_rows)
            attempt=ov+1
            can=True
            infos=[]
            for i in range(height):
                brow=buf[i]
                arow=char_rows[i] if i < len(char_rows) else ""
                tb=trailing_blanks(brow)
                lb=leading_blanks(arow)
                if tb+lb==ov:
                    rb=-1
                    for idx in range(len(brow)-1,-1,-1):
                        if brow[idx]!=' ':
                            rb=idx
                            break
                    lb_idx=len(arow)
                    for idx,ch in enumerate(arow):
                        if ch!=' ':
                            lb_idx=idx
                            break
                    if rb==-1 or lb_idx==len(arow):
                        infos.append(None)
                        continue
                    c1=brow[rb]
                    c2=arow[lb_idx]
                    if layout=='SMUSH':
                        ok,rc=smush_pair(c1,c2,rules,font['hardblank'])
                    else:
                        ok,rc=smush_old(c1,c2,font['hardblank'])
                    if not ok:
                        can=False
                        break
                    infos.append((rb,lb_idx,rc))
                else:
                    infos.append(None)
            if can:
                new_w=cur_w + (max(len(r) for r in char_rows) if char_rows else 0) - attempt
                new_buf=[]
                for i in range(height):
                    brow=buf[i]
                    arow=char_rows[i] if i < len(char_rows) else ""
                    res=[' ']*new_w
                    for j,chb in enumerate(brow):
                        if j<new_w:
                            res[j]=chb
                    start=cur_w-attempt
                    info=infos[i]
                    if info:
                        rb,lb_idx,rc=info
                        if rb<new_w:
                            res[rb]=rc
                        for j in range(lb_idx+1,len(arow)):
                            pos=start+j
                            if 0<=pos<new_w:
                                chn=arow[j]
                                if chn!=' ':
                                    res[pos]=chn
                    else:
                        for j,chn in enumerate(arow):
                            pos=start+j
                            if 0<=pos<new_w and chn!=' ':
                                res[pos]=chn
                    new_buf.append(''.join(res))
                buf=new_buf
            else:
                new_w=cur_w + (max(len(r) for r in char_rows) if char_rows else 0) - ov
                new_buf=[]
                for i in range(height):
                    brow=buf[i]
                    arow=char_rows[i] if i < len(char_rows) else ""
                    res=[' ']*new_w
                    for j,chb in enumerate(brow):
                        if j<new_w:
                            res[j]=chb
                    start=cur_w-ov
                    for j,chn in enumerate(arow):
                        pos=start+j
                        if 0<=pos<new_w and chn!=' ':
                            res[pos]=chn
                    new_buf.append(''.join(res))
                buf=new_buf
    return buf

def render_logical_line(log_line,font,width,justify,text_dir,layout,rules):
    height=font['height']
    hb=font['hardblank']
    if width==1:
        out=[]
        for ch in log_line:
            if ch==' ':
                continue
            cp=ord(ch)
            art=font['cmap'].get(cp)
            if art is None:
                art=font['cmap'].get(32)
                if art is None:
                    art=[""]*height
            disp=[row.replace(hb,' ') for row in art]
            out.extend(disp)
        return out
    if log_line=="":
        return ["" for _ in range(height)]
    if log_line.strip()=="":
        buf=render_word(log_line, font, layout, rules)
        disp=[row.replace(hb,' ') for row in buf]
        cur_w=max(len(r) for r in disp) if disp else 0
        lead=0
        if justify=='CENTER':
            lead=(width - cur_w)//2
        elif justify=='RIGHT':
            lead=width - cur_w -1
        elif justify=='LEFT':
            lead=0
        else:
            lead=width - cur_w -1 if text_dir=='RIGHT' else 0
        if lead<0:
            lead=0
        return [' '*lead + r for r in disp]

    # character by character rendering with word-aware flushing
    # We will implement flush as before
    final=[]
    cur_buf=["" for _ in range(height)]

    def flush():
        nonlocal cur_buf,final
        if not cur_buf or all(b=="" for b in cur_buf):
            return
        disp=[row.replace(hb,' ') for row in cur_buf]
        cur_w=max(len(r) for r in disp) if disp else 0
        lead=0
        if justify=='CENTER':
            lead=(width - cur_w)//2
        elif justify=='RIGHT':
            lead=width - cur_w -1
        elif justify=='LEFT':
            lead=0
        else:
            lead=width - cur_w -1 if text_dir=='RIGHT' else 0
        if lead<0:
            lead=0
        for r in disp:
            final.append(' '*lead + r)
        cur_buf=["" for _ in range(height)]

    def combine(buf,ch):
        cp=ord(ch)
        art=font['cmap'].get(cp)
        if art is None:
            art=font['cmap'].get(32)
            if art is None:
                art=[""]*height
        char_rows = art if layout=='FULL' else trim_char(art,hb)
        if not buf or all(b=="" for b in buf):
            return [r for r in char_rows]
        cur_w=max(len(r) for r in buf)
        if layout=='FULL':
            return [buf[i].ljust(cur_w)+(char_rows[i] if i < len(char_rows) else "") for i in range(height)]
        elif layout=='KERN':
            ov=compute_overlap(buf,char_rows)
            new_w=cur_w + (max(len(r) for r in char_rows) if char_rows else 0) - ov
            new_buf=[]
            for i in range(height):
                brow=buf[i]
                arow=char_rows[i] if i < len(char_rows) else ""
                res=[' ']*new_w
                for j,chb in enumerate(brow):
                    if j<new_w:
                        res[j]=chb
                start=cur_w-ov
                for j,chn in enumerate(arow):
                    pos=start+j
                    if 0<=pos<new_w and chn!=' ':
                        res[pos]=chn
                new_buf.append(''.join(res))
            return new_buf
        elif layout=='OVERLAP':
            ov=compute_overlap(buf,char_rows)
            attempt=ov+1
            new_w=cur_w + (max(len(r) for r in char_rows) if char_rows else 0) - attempt
            new_buf=[]
            for i in range(height):
                brow=buf[i]
                arow=char_rows[i] if i < len(char_rows) else ""
                res=[' ']*new_w
                for j,chb in enumerate(brow):
                    if j<new_w:
                        res[j]=chb
                start=cur_w-attempt
                for j,chn in enumerate(arow):
                    pos=start+j
                    if 0<=pos<new_w and chn!=' ':
                        res[pos]=chn
                new_buf.append(''.join(res))
            return new_buf
        else:
            ov=compute_overlap(buf,char_rows)
            attempt=ov+1
            can=True
            infos=[]
            for i in range(height):
                brow=buf[i]
                arow=char_rows[i] if i < len(char_rows) else ""
                tb=trailing_blanks(brow)
                lb=leading_blanks(arow)
                if tb+lb==ov:
                    rb=-1
                    for idx in range(len(brow)-1,-1,-1):
                        if brow[idx]!=' ':
                            rb=idx
                            break
                    lb_idx=len(arow)
                    for idx,ch in enumerate(arow):
                        if ch!=' ':
                            lb_idx=idx
                            break
                    if rb==-1 or lb_idx==len(arow):
                        infos.append(None)
                        continue
                    c1=brow[rb]
                    c2=arow[lb_idx]
                    if layout=='SMUSH':
                        ok,rc=smush_pair(c1,c2,rules,hb)
                    else:
                        ok,rc=smush_old(c1,c2,hb)
                    if not ok:
                        can=False
                        break
                    infos.append((rb,lb_idx,rc))
                else:
                    infos.append(None)
            if can:
                new_w=cur_w + (max(len(r) for r in char_rows) if char_rows else 0) - attempt
                new_buf=[]
                for i in range(height):
                    brow=buf[i]
                    arow=char_rows[i] if i < len(char_rows) else ""
                    res=[' ']*new_w
                    for j,chb in enumerate(brow):
                        if j<new_w:
                            res[j]=chb
                    start=cur_w-attempt
                    info=infos[i]
                    if info:
                        rb,lb_idx,rc=info
                        if rb<new_w:
                            res[rb]=rc
                        for j in range(lb_idx+1,len(arow)):
                            pos=start+j
                            if 0<=pos<new_w:
                                chn=arow[j]
                                if chn!=' ':
                                    res[pos]=chn
                    else:
                        for j,chn in enumerate(arow):
                            pos=start+j
                            if 0<=pos<new_w and chn!=' ':
                                res[pos]=chn
                    new_buf.append(''.join(res))
                return new_buf
            else:
                new_w=cur_w + (max(len(r) for r in char_rows) if char_rows else 0) - ov
                new_buf=[]
                for i in range(height):
                    brow=buf[i]
                    arow=char_rows[i] if i < len(char_rows) else ""
                    res=[' ']*new_w
                    for j,chb in enumerate(brow):
                        if j<new_w:
                            res[j]=chb
                    start=cur_w-ov
                    for j,chn in enumerate(arow):
                        pos=start+j
                        if 0<=pos<new_w and chn!=' ':
                            res[pos]=chn
                    new_buf.append(''.join(res))
                return new_buf

    # For word wrapping we need to know word boundaries, but we also want to preserve multiple spaces.
    # We'll process the line character by character, but we will also keep a buffer of the current word being built?
    # Simpler: Use the same logic as before for char-by-char, which already matched w20 Hello World? Wait earlier w20 Hello World with char-by-char gave SAME? We had SAME for w20 Hello World after fix to >=? Let's check final_figlet.py (previous version) gave SAME for w20 Hello World after we fixed >=? In earlier run, w20 Hello World was SAME after v5? Actually after v5 we had SAME for w20 Hello World? We had earlier after v5 we had SAME for w20 Hello World? Let's check: In earlier run after v5 we had SAME w=20 Hello World? The run showed SAME w=20 Hello World? Actually the first run after v5 for Hello World gave SAME for w20? We saw "w20 Hello World SAME" earlier? Let's recall: After v5, we had test that w20 Hello World SAME. So char-by-char with >= should give SAME for Hello World.

    # So we will use char-by-char for all, which preserves double spaces as well (since each space is processed individually).

    for ch in log_line:
        if ch==' ':
            if all(b=="" for b in cur_buf):
                continue
            tentative=combine(cur_buf,' ')
            tent_w=max(len(r) for r in tentative) if tentative else 0
            if tent_w >= width:
                flush()
                continue
            else:
                cur_buf=tentative
        else:
            tentative=combine(cur_buf,ch)
            tent_w=max(len(r) for r in tentative) if tentative else 0
            if tent_w >= width and not all(b=="" for b in cur_buf):
                flush()
                cur_buf=combine(["" for _ in range(height)],ch)
            else:
                cur_buf=tentative

    if not all(b=="" for b in cur_buf):
        disp=[row.replace(hb,' ') for row in cur_buf]
        cur_w=max(len(r) for r in disp) if disp else 0
        lead=0
        if justify=='CENTER':
            lead=(width - cur_w)//2
        elif justify=='RIGHT':
            lead=width - cur_w -1
        elif justify=='LEFT':
            lead=0
        else:
            lead=width - cur_w -1 if text_dir=='RIGHT' else 0
        if lead<0:
            lead=0
        for r in disp:
            final.append(' '*lead + r)
    return final

def build_logical_from_args(msg_parts):
    logical=[]
    cur=""
    i=0
    while i < len(msg_parts):
        part=msg_parts[i]
        if part=="":
            if cur!="":
                j=i
                while j < len(msg_parts) and msg_parts[j]=="":
                    j+=1
                n=j-i
                has_future=any(x!="" for x in msg_parts[j:])
                logical.append(cur+" ")
                if has_future:
                    for _ in range(n-1):
                        logical.append("")
                else:
                    for _ in range(max(0,n-1)):
                        logical.append("")
                cur=""
                i=j-1
            else:
                j=i
                while j < len(msg_parts) and msg_parts[j]=="":
                    j+=1
                n=j-i
                has_future=any(x!="" for x in msg_parts[j:])
                if has_future:
                    for _ in range(n):
                        logical.append("")
                else:
                    for _ in range(max(0,n-1)):
                        logical.append("")
                i=j-1
        else:
            if cur=="":
                cur=part
            else:
                cur=cur+" "+part
        i+=1
    if cur!="":
        logical.append(cur)
    if logical and logical[-1]=="":
        logical.pop()
    return logical

