def build_logical_from_args(msg_parts):
    logical=[]
    cur=""
    i=0
    while i < len(msg_parts):
        part=msg_parts[i]
        if part=="":
            if cur!="":
                j=i
                while j < len(msg_parts) and msg_parts[j]=="":
                    j+=1
                n=j-i
                has_future=any(x!="" for x in msg_parts[j:])
                logical.append(cur+" ")
                if has_future:
                    for _ in range(n-1):
                        logical.append("")
                else:
                    for _ in range(max(0,n-1)):
                        logical.append("")
                cur=""
                i=j-1
            else:
                j=i
                while j < len(msg_parts) and msg_parts[j]=="":
                    j+=1
                n=j-i
                has_future=any(x!="" for x in msg_parts[j:])
                if has_future:
                    for _ in range(n):
                        logical.append("")
                else:
                    for _ in range(max(0,n-1)):
                        logical.append("")
                i=j-1
        else:
            if cur=="":
                cur=part
            else:
                cur=cur+" "+part
        i+=1
    if cur!="":
        logical.append(cur)
    if logical and logical[-1]=="":
        logical.pop()
    return logical

