                content=l[:-1]
            else:
                content=l
            char_lines.append(content)
        cmap[code]=char_lines
        idx+=height
    return {'hardblank':hardblank,'height':height,'old_layout':old_layout,'print_dir':print_dir,'full_layout':full_layout,'cmap':cmap},None

def find_font_file(fontname,fontdir):
    is_path=('/' in fontname or '\\' in fontname) or os.path.isabs(fontname)
    def try_path(p):
        return p if os.path.isfile(p) else None
    def with_exts(base):
        low=base.lower()
        if low.endswith('.flf') or low.endswith('.tlf'):
            return [base]
        return [base+'.flf',base+'.tlf',base]
    if is_path:
        for cand in with_exts(fontname):
            r=try_path(cand)
            if r:
                return r
        return None
    else:
        dirs=[]
        if fontdir:
            dirs.append(fontdir)
        dirs.append('.')
        env_dir=os.environ.get('FIGLET_FONTDIR')
        if env_dir:
            for d in env_dir.split(os.pathsep):
                if d and d not in dirs:
                    dirs.append(d)
        uniq=[]
        seen=set()
        for d in dirs:
            if d not in seen:
                seen.add(d)
                uniq.append(d)
        for d in uniq:
            for cand in with_exts(os.path.join(d,fontname)):
                r=try_path(cand)
                if r:
                    return r
        return None

