    para_mode='NORMAL'
    valid_no_arg=set(list("cklnoprstvxDELNRSWX"))
    valid_arg=set(['d','f','m','w','C','I'])
    args=sys.argv[1:]
    i=0
    msg_parts=[]
    while i < len(args):
        arg=args[i]
        if arg=='--':
            msg_parts.extend(args[i+1:])
            break
        if arg.startswith('-') and len(arg)>1 and arg!="-":
            if arg[1] in valid_arg:
                flag=arg[1]
                val=arg[2:] if len(arg)>2 else (args[i+1] if i+1 < len(args) else None)
                if len(arg)==2 and val is not None:
                    i+=1
                if flag=='d':
                    fontdir=val
                elif flag=='f':
                    fontname=val
                elif flag=='m':
                    try:
                        smush_mode=int(val) if val is not None else 0
                    except:
                        smush_mode=0
                    if smush_mode==0:
                        explicit_layout='KERN'
                        smush_mode=None
                    elif smush_mode==-1:
                        explicit_layout='FULL'
                        smush_mode=None
                    elif smush_mode==-2:
                        explicit_layout='SMUSH'
                        smush_mode=None
                    else:
                        explicit_layout='SMUSH'
                        if (smush_mode & 63)==0 and smush_mode!=0:
                            smush_mode=63
                        else:
                            if smush_mode>0:
                                smush_mode=smush_mode & 63
                                if smush_mode==0:
                                    smush_mode=63
                            else:
                                smush_mode=abs(smush_mode) & 63
                                if smush_mode==0:
                                    smush_mode=63
                elif flag=='w':
                    try:
                        w=int(val) if val is not None else 80
