                                sys.stderr.write("from  http://www.figlet.org/under UNIX utilities.\n")
                                sys.exit(1)
                            else:
                                sys.stderr.write(f"{prog}: invalid option -- '{ch}'\n")
                                print_usage(prog, sys.stderr)
