            sys.exit(0)
        elif infocode==1:
            sys.stdout.write(f"{VERSION_NUM}\n")
            sys.exit(0)
        elif infocode==2:
            if fontdir:
                sys.stdout.write(f"{fontdir}\n")
            else:
                env_dir=os.environ.get('FIGLET_FONTDIR')
                if env_dir:
                    sys.stdout.write(f"{env_dir}\n")
