                smush_rules=smush_mode
        elif explicit_layout=='KERN':
            layout_type='KERN'
            smush_rules=0
        elif explicit_layout=='FULL':
            layout_type='FULL'
            smush_rules=0
        elif explicit_layout=='OVERLAP':
            layout_type='OVERLAP'
            smush_rules=0
        elif explicit_layout=='SMUSH_OLD':
            layout_type='SMUSH_OLD'
            smush_rules=default_rules
        else:
            layout_type=explicit_layout
            smush_rules=smush_mode if smush_mode is not None else 0

    if text_dir=='X':
        effective_dir='RIGHT' if font_data['print_dir']==1 else 'LEFT'
    elif text_dir=='LEFT':
        effective_dir='LEFT'
    else:
        effective_dir='RIGHT'

    effective_justify=justify
    if justify=='X':
        effective_justify='RIGHT' if effective_dir=='RIGHT' else 'LEFT'

    combined_trans={}
    formatA_maps=[]
    for ctrlname in controls:
        ctrl_path=find_control_file(ctrlname, fontdir)
        if not ctrl_path:
            sys.stderr.write(f"{prog}: {ctrlname}: Unable to open control file\n")
