            if not tmp or all(b=="" for b in tmp):
                tmp=[r for r in char_rows]
                continue
            cur_w=max(len(r) for r in tmp)
            if layout=='FULL':
                tmp=[tmp[i].ljust(cur_w)+(char_rows[i] if i < len(char_rows) else "") for i in range(height)]
            elif layout=='KERN':
                ov=compute_overlap(tmp,char_rows)
                new_w=cur_w + (max(len(r) for r in char_rows) if char_rows else 0) - ov
                new_buf=[]
                for i in range(height):
                    brow=tmp[i]
                    arow=char_rows[i] if i < len(char_rows) else ""
                    res=[' ']*new_w
                    for j,chb in enumerate(brow):
                        if j<new_w:
                            res[j]=chb
                    start=cur_w-ov
                    for j,chn in enumerate(arow):
                        pos=start+j
                        if 0<=pos<new_w and chn!=' ':
                            res[pos]=chn
                    new_buf.append(''.join(res))
                tmp=new_buf
            elif layout=='OVERLAP':
                ov=compute_overlap(tmp,char_rows)
                attempt=ov+1
                new_w=cur_w + (max(len(r) for r in char_rows) if char_rows else 0) - attempt
                new_buf=[]
                for i in range(height):
                    brow=tmp[i]
                    arow=char_rows[i] if i < len(char_rows) else ""
                    res=[' ']*new_w
                    for j,chb in enumerate(brow):
                        if j<new_w:
                            res[j]=chb
                    start=cur_w-attempt
                    for j,chn in enumerate(arow):
                        pos=start+j
                        if 0<=pos<new_w and chn!=' ':
                            res[pos]=chn
                    new_buf.append(''.join(res))
                tmp=new_buf
            else:
                ov=compute_overlap(tmp,char_rows)
                attempt=ov+1
                can=True
                infos=[]
                for i in range(height):
                    brow=tmp[i]
                    arow=char_rows[i] if i < len(char_rows) else ""
                    tb=trailing_blanks(brow)
                    lb=leading_blanks(arow)
                    if tb+lb==ov:
                        rb=-1
                        for idx in range(len(brow)-1,-1,-1):
                            if brow[idx]!=' ':
                                rb=idx
                                break
                        lb_idx=len(arow)
                        for idx,ch in enumerate(arow):
                            if ch!=' ':
                                lb_idx=idx
                                break
                        if rb==-1 or lb_idx==len(arow):
                            infos.append(None)
                            continue
                        c1=brow[rb]
                        c2=arow[lb_idx]
                        if layout=='SMUSH':
                            ok,rc=smush_pair(c1,c2,rules,hb)
                        else:
                            ok,rc=smush_old(c1,c2,hb)
                        if not ok:
                            can=False
                            break
                        infos.append((rb,lb_idx,rc))
                    else:
                        infos.append(None)
                if can:
                    new_w=cur_w + (max(len(r) for r in char_rows) if char_rows else 0) - attempt
                    new_buf=[]
                    for i in range(height):
                        brow=tmp[i]
                        arow=char_rows[i] if i < len(char_rows) else ""
                        res=[' ']*new_w
                        for j,chb in enumerate(brow):
                            if j<new_w:
                                res[j]=chb
                        start=cur_w-attempt
                        info=infos[i]
                        if info:
                            rb,lb_idx,rc=info
                            if rb<new_w:
                                res[rb]=rc
                            for j in range(lb_idx+1,len(arow)):
                                pos=start+j
                                if 0<=pos<new_w:
                                    chn=arow[j]
                                    if chn!=' ':
                                        res[pos]=chn
                        else:
                            for j,chn in enumerate(arow):
                                pos=start+j
                                if 0<=pos<new_w and chn!=' ':
                                    res[pos]=chn
                        new_buf.append(''.join(res))
                    tmp=new_buf
                else:
                    new_w=cur_w + (max(len(r) for r in char_rows) if char_rows else 0) - ov
                    new_buf=[]
                    for i in range(height):
                        brow=tmp[i]
                        arow=char_rows[i] if i < len(char_rows) else ""
                        res=[' ']*new_w
                        for j,chb in enumerate(brow):
                            if j<new_w:
                                res[j]=chb
                        start=cur_w-ov
                        for j,chn in enumerate(arow):
                            pos=start+j
                            if 0<=pos<new_w and chn!=' ':
                                res[pos]=chn
                        new_buf.append(''.join(res))
                    tmp=new_buf
        return tmp

    # For word wrapping we use word split to keep words together, but we also need to handle multiple spaces? 
    # The original figlet collapses multiple spaces into one for wrapping purposes? Actually earlier we saw "A  B" width 18 vs "A B" 17, so multiple spaces are preserved when rendered without wrapping. For wrapping, spaces between words are treated as single space separator? Let's use split() to collapse for wrapping decision, but for rendering we will preserve single space between words.

    words=log_line.split()
    for word in words:
        if all(b=="" for b in cur_buf):
            wb=render_word(word,font,layout,rules)
            ww=max(len(r) for r in wb) if wb else 0
            if ww >= width:
                for ch in word:
                    tentative=combine(cur_buf,ch)
                    tent_w=max(len(r) for r in tentative) if tentative else 0
                    if tent_w >= width and not all(b=="" for b in cur_buf):
                        flush()
                        cur_buf=combine(["" for _ in range(height)],ch)
                    else:
                        cur_buf=tentative
            else:
                cur_buf=wb
        else:
            tentative_space=combine(cur_buf,' ')
            tentative_full=combine(tentative_space,word)
            tent_w=max(len(r) for r in tentative_full) if tentative_full else 0
            if tent_w >= width:
                flush()
                wb=render_word(word,font,layout,rules)
                ww=max(len(r) for r in wb) if wb else 0
                if ww >= width:
                    cur_buf=["" for _ in range(height)]
                    for ch in word:
                        tentative=combine(cur_buf,ch)
                        tent_w2=max(len(r) for r in tentative) if tentative else 0
                        if tent_w2 >= width and not all(b=="" for b in cur_buf):
                            flush()
                            cur_buf=combine(["" for _ in range(height)],ch)
                        else:
                            cur_buf=tentative
                else:
                    cur_buf=wb
            else:
                cur_buf=tentative_full

    if not all(b=="" for b in cur_buf):
        disp=[row.replace(hb,' ') for row in cur_buf]
        cur_w=max(len(r) for r in disp) if disp else 0
        lead=0
        if justify=='CENTER':
            lead=(width - cur_w)//2
        elif justify=='RIGHT':
            lead=width - cur_w -1
        elif justify=='LEFT':
            lead=0
        else:
            lead=width - cur_w -1 if text_dir=='RIGHT' else 0
        if lead<0:
            lead=0
        for r in disp:
            final.append(' '*lead + r)
    return final

def build_logical_from_args(msg_parts):
    logical=[]
    cur=""
    i=0
    while i < len(msg_parts):
        part=msg_parts[i]
        if part=="":
            if cur!="":
                j=i
                while j < len(msg_parts) and msg_parts[j]=="":
                    j+=1
                n=j-i
                has_future=any(x!="" for x in msg_parts[j:])
                logical.append(cur+" ")
                if has_future:
                    for _ in range(n-1):
                        logical.append("")
                else:
                    for _ in range(max(0,n-1)):
                        logical.append("")
                cur=""
                i=j-1
            else:
                j=i
                while j < len(msg_parts) and msg_parts[j]=="":
                    j+=1
                n=j-i
                has_future=any(x!="" for x in msg_parts[j:])
                if has_future:
                    for _ in range(n):
                        logical.append("")
                else:
                    for _ in range(max(0,n-1)):
                        logical.append("")
                i=j-1
        else:
            if cur=="":
                cur=part
            else:
                cur=cur+" "+part
        i+=1
    if cur!="":
        logical.append(cur)
    if logical and logical[-1]=="":
        logical.pop()
    return logical

