            if ww >= width:
                for ch in word:
                    tentative=combine(cur_buf,ch)
                    tent_w=max(len(r) for r in tentative) if tentative else 0
                    if tent_w >= width and not all(b=="" for b in cur_buf):
                        flush()
                        cur_buf=combine(["" for _ in range(height)],ch)
                    else:
                        cur_buf=tentative
            else:
                cur_buf=wb
        else:
            tentative_space=combine(cur_buf,' ')
            tentative_full=combine(tentative_space,word)
            tent_w=max(len(r) for r in tentative_full) if tentative_full else 0
            if tent_w >= width:
                flush()
                wb=render_word(word,font,layout,rules)
                ww=max(len(r) for r in wb) if wb else 0
                if ww >= width:
                    cur_buf=["" for _ in range(height)]
                    for ch in word:
                        tentative=combine(cur_buf,ch)
                        tent_w2=max(len(r) for r in tentative) if tentative else 0
                        if tent_w2 >= width and not all(b=="" for b in cur_buf):
                            flush()
                            cur_buf=combine(["" for _ in range(height)],ch)
                        else:
                            cur_buf=tentative
                else:
                    cur_buf=wb
            else:
                cur_buf=tentative_full

    if not all(b=="" for b in cur_buf):
        disp=[row.replace(hb,' ') for row in cur_buf]
        cur_w=max(len(r) for r in disp) if disp else 0
        lead=0
        if justify=='CENTER':
            lead=(width - cur_w)//2
        elif justify=='RIGHT':
            lead=width - cur_w -1
        elif justify=='LEFT':
            lead=0
        else:
            lead=width - cur_w -1 if text_dir=='RIGHT' else 0
        if lead<0:
            lead=0
        for r in disp:
            final.append(' '*lead + r)
    return final

def build_logical_from_args(msg_parts):
    logical=[]
    cur=""
    i=0
    while i < len(msg_parts):
        part=msg_parts[i]
        if part=="":
            if cur!="":
                j=i
                while j < len(msg_parts) and msg_parts[j]=="":
                    j+=1
                n=j-i
                has_future=any(x!="" for x in msg_parts[j:])
                logical.append(cur+" ")
                if has_future:
                    for _ in range(n-1):
                        logical.append("")
                else:
                    for _ in range(max(0,n-1)):
                        logical.append("")
                cur=""
                i=j-1
            else:
                j=i
                while j < len(msg_parts) and msg_parts[j]=="":
                    j+=1
                n=j-i
                has_future=any(x!="" for x in msg_parts[j:])
                if has_future:
                    for _ in range(n):
                        logical.append("")
                else:
                    for _ in range(max(0,n-1)):
                        logical.append("")
                i=j-1
        else:
            if cur=="":
                cur=part
            else:
                cur=cur+" "+part
        i+=1
    if cur!="":
        logical.append(cur)
    if logical and logical[-1]=="":
        logical.pop()
    return logical

