def expand_control_token(token):
    def parse_single(s,idx):
        if idx>=len(s):
            return None,idx
        ch=s[idx]
        if ch=='\\':
            if idx+1>=len(s):
                return ord('\\'),idx+1
            nxt=s[idx+1]
