def expand_control_token(token):
    def parse_single(s,idx):
        if idx>=len(s):
            return None,idx
        ch=s[idx]
        if ch=='\\':
            if idx+1>=len(s):
                return ord('\\'),idx+1
            nxt=s[idx+1]
            if nxt=='-':
                return ord('-'),idx+2
            if nxt=='\\':
                return ord('\\'),idx+2
            if s[idx+1:idx+3].lower()=='0x':
                j=idx+3
                hexd=""
                while j<len(s) and s[j] in "0123456789ABCDEFabcdef":
                    hexd+=s[j]
                    j+=1
                    if len(hexd)>=6:
                        break
                if hexd:
                    try:
                        return int(hexd,16),j
                    except:
                        return ord('\\'),idx+1
                else:
                    return ord('\\'),idx+1
            if nxt.isdigit():
                j=idx+1
                num=""
                while j<len(s) and s[j].isdigit():
                    num+=s[j]
                    j+=1
                    if len(num)>=4:
                        break
                if num:
                    try:
                        return int(num),j
                    except:
                        return ord(nxt),idx+1
                else:
                    return ord(nxt),idx+2
            else:
                return ord(nxt),idx+2
        else:
            return ord(ch),idx+1
    placeholder="\0"
